package main

import (
	"fmt"
	"os"
	"strings"
	"time"
)

// Log levels, matching the observed output format of the original tool:
//
//	2026-01-02 03:04:05 [INFO]  message
//
// When stderr is a terminal, the level name is colorized.
var logLevelColors = map[string]string{
	"DEBUG": "\x1b[36;1m",
	"INFO":  "\x1b[32;1m",
	"WARN":  "\x1b[33;1m",
	"ERROR": "\x1b[31;1m",
}

var debugEnabled = false

func colorEnabled() bool {
	if fi, err := os.Stderr.Stat(); err == nil {
		return fi.Mode()&os.ModeCharDevice != 0
	}
	return false
}

func logWrite(level, format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	levelName := level
	color := ""
	if colorEnabled() {
		color = logLevelColors[levelName]
	}
	ts := time.Now().Format("2006-01-02 15:04:05")
	// level name is padded so that "[" + level + "]" occupies a fixed width of
	// 8 chars followed by a space.
	pad := 6 - len(levelName)
	if pad < 0 {
		pad = 0
	}
	if color != "" {
		fmt.Fprintf(os.Stderr, "%s [%s%s\x1b[0m]%s %s\n", ts, color, levelName, strings.Repeat(" ", pad), msg)
	} else {
		fmt.Fprintf(os.Stderr, "%s [%s]%s %s\n", ts, levelName, strings.Repeat(" ", pad), msg)
	}
}

func logDebugf(format string, args ...interface{}) {
	if debugEnabled {
		logWrite("DEBUG", format, args...)
	}
}

func logInfof(format string, args ...interface{}) {
	logWrite("INFO", format, args...)
}

func logWarnf(format string, args ...interface{}) {
	logWrite("WARN", format, args...)
}

func logErrorf(format string, args ...interface{}) {
	logWrite("ERROR", format, args...)
}
