package main

import (
	"fmt"
	"os"
	"strings"
)

// optRecord captures how a single option was specified on the command line.
type optRecord struct {
	value string
	set   bool
	skip  bool // specified via --skip-<name> form
}

// parsedArgs is the result of parsing the command line for one command.
type parsedArgs struct {
	cmdName string
	opts    map[string]*optRecord
	args    []string
}

func (p *parsedArgs) has(name string) bool {
	r, ok := p.opts[name]
	return ok && r.set
}

func (p *parsedArgs) value(name string) string {
	r, ok := p.opts[name]
	if !ok || !r.set {
		return ""
	}
	return r.value
}

func (p *parsedArgs) isSet(name string) bool {
	return p.has(name)
}

func (p *parsedArgs) skipped(name string) bool {
	r, ok := p.opts[name]
	return ok && r.skip
}

var globalOptionNames = []string{
	"connect-options", "debug", "flavor", "help", "host", "host-wrapper",
	"ignore-func", "ignore-proc", "ignore-schema", "ignore-table", "my-cnf",
	"password", "port", "schema", "socket", "ssl-mode", "user", "version",
}

func commandHasOption(cmdName, name string) bool {
	opts, ok := commandOptions[cmdName]
	if !ok {
		return false
	}
	for _, o := range opts {
		if o.name == name {
			return true
		}
	}
	return false
}

func lookupOpt(cmdName, name string) (opt, bool) {
	opts, ok := commandOptions[cmdName]
	if !ok {
		return opt{}, false
	}
	for _, o := range opts {
		if o.name == name {
			return o, true
		}
	}
	return opt{}, false
}

func isGlobalOption(name string) bool {
	for _, g := range globalOptionNames {
		if g == name {
			return true
		}
	}
	return false
}

// parseBool implements the truthiness rules observed in the original binary:
// empty string, "0", "false" and "off" (case-insensitive, after trimming) are
// false; anything else is true.
func parseBool(s string) bool {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "", "0", "false", "off":
		return false
	}
	return true
}

// cliError represents a fatal error during command line parsing.
type cliError struct {
	msg string
}

func (e cliError) Error() string { return e.msg }

func parseArgs(argv []string) (*parsedArgs, error) {
	p := &parsedArgs{opts: make(map[string]*optRecord)}
	i := 0
	cmdName := ""
	// Phase 1: global options, then the command name.
	for i < len(argv) {
		tok := argv[i]
		if tok == "--" {
			i++
			break
		}
		if len(tok) < 2 || tok[0] != '-' {
			break
		}
		// parse one option (may consume following tokens)
		consumed, err := p.parseToken(cmdName, tok, argv[i+1:], true)
		if err != nil {
			return nil, err
		}
		if p.stopRequested {
			i += consumed
			break
		}
		i += consumed
	}
	if i < len(argv) && argv[i] != "--" {
		cmdName = argv[i]
		i++
		p.cmdName = cmdName
	} else {
		p.cmdName = ""
	}
	// Phase 2
	for i < len(argv) {
		tok := argv[i]
		if p.stopRequested {
			p.args = append(p.args, argv[i:]...)
			break
		}
		if tok == "--" {
			i++
			p.args = append(p.args, argv[i:]...)
			break
		}
		if len(tok) > 1 && tok[0] == '-' {
			consumed, err := p.parseToken(p.cmdName, tok, argv[i+1:], false)
			if err != nil {
				return nil, err
			}
			i += consumed
			continue
		}
		p.args = append(p.args, tok)
		i++
	}
	return p, nil
}
