func usageKey(o opt) string {
	var sb strings.Builder
	if o.short != "" {
		sb.WriteString("  -" + o.short + ", ")
	} else {
		sb.WriteString("      ")
	}
	if o.skip {
		sb.WriteString("--[skip-]")
	} else {
		sb.WriteString("--")
	}
	sb.WriteString(o.name)
	if o.val && !o.optval {
		sb.WriteString(" value")
	}
	if o.optval {
		sb.WriteString("[=value]")
	}
