// printCommandHelp writes the help text for a single command (or the suite when
// name is empty) to stdout.
func printCommandHelp(name string) {
	fmt.Printf("\n")
	if name == "" {
		fmt.Printf("Usage:  skeema [<options>] <command>\n")
	} else {
		fmt.Printf("Usage:  skeema %s [<options>]%s\n", name, usageArgsSuffix(name))
	}
	fmt.Printf("\n")
	for _, line := range commandDescription(name) {
		fmt.Printf("%s\n", line)
	}
	fmt.Printf("\n")
	if name == "" {
		fmt.Printf("Commands:\n")
		width := 0
		for _, cn := range commandNames {
			if len(cn) > width {
				width = len(cn)
			}
		}
		for _, cn := range commandNames {
			fmt.Printf("      %-*s  %s\n", width, cn, commandListDescription(cn))
		}
		fmt.Printf("\n")
	} else {
		// group options
		opts := commandOptions[name]
		seenGroups := []string{}
		byGroup := map[string][]opt{}
		for _, o := range opts {
			if o.group == "" {
				continue
			}
			if _, ok := byGroup[o.group]; !ok {
				seenGroups = append(seenGroups, o.group)
			}
			byGroup[o.group] = append(byGroup[o.group], o)
		}
		for _, g := range seenGroups {
			printOptionGroup(g, byGroup[g])
		}
	}
	if name == "" {
		printOptionGroup("Global Options", globalOptsForSuite())
		fmt.Printf("\nComplete documentation for this command suite is available online:\n")
		fmt.Printf("%s\n", docURLPrefix)
		fmt.Printf("\n")
	} else {
		fmt.Printf("\nComplete documentation for this command is available online:\n")
		fmt.Printf("%s/%s\n", docURLPrefix, name)
		fmt.Printf("\n")
	}
