func usageArgsSuffix(name string) string {
	a, ok := commandUsageArgs[name]
	if !ok || a == "" {
		return ""
	}
	return " " + a
}

func commandListDescription(name string) string {
	switch name {
	case "add-environment":
		return "Add a new named environment to an existing host directory"
	case "diff":
		return "Compare a DB server's schemas to the filesystem"
	case "format":
		return "Normalize format of filesystem representation of database objects"
	case "help":
		return "Display usage information"
	case "init":
		return "Save a DB server's schemas to the filesystem"
	case "lint":
		return "Check for problems in filesystem representation of database objects"
	case "pull":
		return "Update the filesystem representation of schemas"
	case "push":
		return "Alter objects on DBs to reflect the filesystem representation"
	case "version":
		return "Display program version"
	}
	return ""
}

func globalOptsForSuite() []opt {
	opts := commandOptions["version"]
	var result []opt
	for _, o := range opts {
		if o.hidden {
			continue
		}
		result = append(result, o)
	}
	sort.SliceStable(result, func(i, j int) bool { return result[i].name < result[j].name })
	return result
}

func printOptionGroup(name string, opts []opt) {
	fmt.Printf("%s:\n", name)
	maxLen := 0
	for _, o := range opts {
		if len(usageKey(o)) > maxLen {
			maxLen = len(usageKey(o))
		}
	}
	for _, o := range opts {
		key := usageKey(o)
		fmt.Printf("%s%s  %s\n", key, strings.Repeat(" ", maxLen-len(key)+2), optionHelpText(o))
	}
	fmt.Printf("\n")
}

func optionHelpText(o opt) string {
	var sb strings.Builder
	sb.WriteString(o.desc)
	if o.valid != "" {
		sb.WriteString(" (valid values: " + o.valid + ")")
	}
	if o.def != "" {
		sb.WriteString(fmt.Sprintf(" (default %q)", o.def))
	}
	return sb.String()
}
