func main() {
	argv := os.Args[1:]
	p, err := parseArgs(argv)
	if err != nil {
		if ce, ok := err.(cliError); ok {
			logErrorf("CLI: %s", ce.msg)
		} else {
			logErrorf("%s", err.Error())
		}
		os.Exit(78)
	}

	cmdName := p.cmdName
	// --version short-circuits everything
	if p.versionFlag {
		printVersion()
		finishExit("version", 0)
	}
	if p.helpRequested {
		target := p.helpTarget
		if target == "" {
			target = cmdName
		}
		if target == "" || target == "help" {
			printCommandHelp("")
			finishExit("help", 0)
		}
		if !validCommand(target) {
			logErrorf("Unknown command %q", target)
			finishExit("help", 2)
		}
		if target == "version" {
			printVersion()
			finishExit("version", 0)
		}
		printCommandHelp(target)
		finishExit("help", 0)
	}

	if cmdName == "" {
		printCommandHelp("")
		os.Exit(0)
	}

	if !validCommand(cmdName) {
		logErrorf("Unknown command %q", cmdName)
		os.Exit(78)
	}

	if cmdName == "version" {
		printVersion()
		finishExit("version", 0)
	}
	if cmdName == "help" {
		if len(p.args) == 0 {
			printCommandHelp("")
			finishExit("help", 0)
		}
		target := p.args[0]
		if !validCommand(target) {
			logErrorf("Unknown command %q", target)
			finishExit("help", 2)
		}
		if target == "version" {
			printVersion()
			finishExit("version", 0)
		}
		printCommandHelp(target)
		finishExit("help", 0)
	}

	exitCode := runCommand(cmdName, p)
	finishExit(cmdName, exitCode)
}

func validCommand(name string) bool {
	for _, c := range commandNames {
		if c == name {
			return true
		}
	}
	return false
}

func printVersion() {
	fmt.Println(versionString)
}

func finishExit(cmdName string, code int) {
	if debugEnabled {
		if code == 0 && exitCodeSuccessSuffix[cmdName] {
			logDebugf("Exit code %d (SUCCESS)", code)
		} else {
			logDebugf("Exit code %d", code)
		}
	}
	os.Exit(code)
}
