func argCountError(cmdName string, args []string) error {
	if len(args) > commandMaxArgs[cmdName] {
		return fmt.Errorf("Extra command-line arg %q supplied; command %s takes a max of %d args", args[commandMaxArgs[cmdName]], cmdName, commandMaxArgs[cmdName])
