			return nil, fmt.Errorf("%s line %d: Unknown option %q", path, lineNum, name)
		}
		parsed = append(parsed, parsedLine{cur, strings.ToLower(name), value})
	}
	for _, pl := range parsed {
		pl.section.set(pl.name, pl.value)
		if reason, ok := deprecatedOptionReasons[pl.name]; ok {
			logWarnf("%s: Option %s is deprecated. %s", path, pl.name, reason)
		}
	}
	return f, nil
