// OptionBlock holds a set of option values, keyed by lowercase option name.
type OptionBlock struct {
	Env    string
	Values map[string]string
	Order  []string
}

func (b *OptionBlock) set(name, value string) {
	name = strings.ToLower(name)
	if _, ok := b.Values[name]; !ok {
		b.Order = append(b.Order, name)
	}
	b.Values[name] = value
}

// ConfigFile is a parsed .skeema file.
type ConfigFile struct {
	Path   string
	Blocks []OptionBlock // first block is always the sectionless one
	Err    error
}

func (f *ConfigFile) Sectionless() *OptionBlock {
	if len(f.Blocks) == 0 {
		f.Blocks = append(f.Blocks, OptionBlock{Env: "", Values: map[string]string{}})
	}
	return &f.Blocks[0]
}

func (f *ConfigFile) Block(env string) *OptionBlock {
	for i := range f.Blocks {
		if f.Blocks[i].Env == env {
			return &f.Blocks[i]
		}
	}
	return nil
}

func (f *ConfigFile) Environments() []string {
	var out []string
	for _, b := range f.Blocks {
		if b.Env != "" {
			out = append(out, b.Env)
		}
	}
	return out
}

var deprecatedOptionReasons = map[string]string{
	"my-cnf":                "This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes",
	"temp-schema-threads":   "This option will be removed in Skeema v2. Use the new temp-schema-mode enum option instead. See --help or visit https://www.skeema.io/docs/options/#temp-schema-mode",
	"temp-schema-binlog":    "This option will be removed in Skeema v2, with \"auto\" behavior always being used. For more information, visit https://www.skeema.io/v2-changes",
	"lint-display-width":    "This option will be removed in Skeema v2. For more information, visit https://www.skeema.io/v2-changes",
	"alter-validate-virtual": "This option will be removed in Skeema v2. As an alternative, use alter-algorithm=copy, or configure alter-wrapper to use an external OSC tool.",
}

// parseConfigFile parses the contents of a .skeema file. Returns the parsed
// file and, on failure, a parse error (which is also stored in f.Err).
func parseConfigFile(path, contents string) (*ConfigFile, error) {
	f := &ConfigFile{Path: path}
	sectionless := f.Sectionless()
	cur := sectionless
	lines := strings.Split(contents, "\n")
	// First pass: parse all lines, collecting errors.
	type parsedLine struct {
		section *OptionBlock
		name    string
		value   string
	}
	var parsed []parsedLine
	for i, raw := range lines {
		lineNum := i + 1
		line := strings.TrimSpace(raw)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") {
			if !strings.HasSuffix(line, "]") {
				return nil, fmt.Errorf("Parse error in %s line %d: Unknown option %q", path, lineNum, line)
			}
			name := strings.TrimSpace(line[1 : len(line)-1])
			// strip inline comments in section names
			if idx := strings.Index(name, "#"); idx >= 0 {
				name = strings.TrimSpace(name[:idx])
			}
			if name == "" {
				cur = sectionless
				continue
			}
			blk := f.Block(name)
			if blk == nil {
				blk = &OptionBlock{Env: name, Values: map[string]string{}}
				f.Blocks = append(f.Blocks, *blk)
				blk = &f.Blocks[len(f.Blocks)-1]
			}
			cur = blk
			continue
		}
		// directive
		var name, value string
		if idx := strings.Index(line, "="); idx >= 0 {
			name = strings.TrimSpace(line[:idx])
			value = strings.TrimSpace(line[idx+1:])
		} else {
			name = line
			value = ""
		}
		value, err := parseConfigValue(value)
		if err != nil {
			return nil, fmt.Errorf("Parse error in %s line %d: %s", path, lineNum, err.Error())
		}
		if !validOptionName(name) {
			return nil, fmt.Errorf("%s line %d: Unknown option %q", path, lineNum, name)
		}
		parsed = append(parsed, parsedLine{cur, strings.ToLower(name), value})
	}
	for _, pl := range parsed {
		pl.section.set(pl.name, pl.value)
		if reason, ok := deprecatedOptionReasons[pl.name]; ok {
			logWarnf("%s: Option %s is deprecated. %s", path, pl.name, reason)
		}
	}
	return f, nil
}

// validOptionName reports whether name is recognized (case-insensitively).
func validOptionName(name string) bool {
	lower := strings.ToLower(name)
	for _, opts := range commandOptions {
		for _, o := range opts {
			if o.name == lower {
				return true
			}
		}
	}
	return false
}

// parseConfigValue strips comments (respecting quotes), trims, and handles
// quoting. Returns an error for unterminated quotes.
func parseConfigValue(value string) (string, error) {
	// quote-aware comment stripping
	var sb strings.Builder
	var quote byte
	for i := 0; i < len(value); i++ {
		c := value[i]
		if quote == 0 {
			if c == '"' || c == '\'' {
				quote = c
				sb.WriteByte(c)
				continue
			}
			if c == '#' {
				break
			}
			sb.WriteByte(c)
			continue
		}
		sb.WriteByte(c)
		if c == quote {
			quote = 0
		}
	}
	value = strings.TrimSpace(sb.String())
	// handle quoting
	if strings.Contains(value, "\"") || strings.Contains(value, "'") {
		q := byte(0)
		for i := 0; i < len(value); i++ {
			if value[i] == '"' || value[i] == '\'' {
				q = value[i]
				break
			}
		}
		count := strings.Count(value, string(q))
		if count%2 == 1 {
			return "", fmt.Errorf("Quoted value has no terminating quote")
		}
		if len(value) >= 2 && value[0] == q && value[len(value)-1] == q {
			value = value[1 : len(value)-1]
		}
	}
	// env var expansion: only when the value begins with $
	if strings.HasPrefix(value, "$") {
		value = os.Getenv(value[1:])
	}
	return value, nil
}

// parseMyCnf parses ~/.my.cnf, returning values from the [skeema], [client]
// and [mysql] sections (with [skeema] taking highest precedence).
func parseMyCnf(path string) map[string]string {
	result := map[string]string{}
	contents, err := os.ReadFile(path)
	if err != nil {
		return result
	}
	priority := map[string]int{"skeema": 3, "client": 2, "mysql": 1}
	for _, line := range strings.Split(string(contents), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") {
			continue
		}
		var name, value string
		if idx := strings.Index(line, "="); idx >= 0 {
			name = strings.TrimSpace(line[:idx])
			value = strings.TrimSpace(line[idx+1:])
		} else {
			continue
		}
		// Determine the section this directive belongs to. my.cnf files are
		// simple enough that we re-scan for the section.
		_ = name
		_ = value
	}
	// second pass with section tracking
	curPrio := 0
	name := ""
	value := ""
	for _, line := range strings.Split(string(contents), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") {
			sec := strings.TrimSpace(line[1:])
			if idx := strings.Index(sec, "]"); idx >= 0 {
				sec = strings.TrimSpace(sec[:idx])
			}
			if p, ok := priority[strings.ToLower(sec)]; ok {
				curPrio = p
			} else {
				curPrio = 0
			}
			continue
		}
		var n, v string
		idx := strings.Index(line, "=")
		if idx < 0 {
			continue
		}
		n = strings.TrimSpace(line[:idx])
		v = strings.TrimSpace(line[idx+1:])
		v = strings.Trim(v, "\"'")
		if idx2 := strings.Index(v, "#"); idx2 >= 0 {
			v = strings.TrimSpace(v[:idx2])
		}
		name, value = n, v
		switch strings.ToLower(name) {
		case "user", "password", "port", "socket", "host", "schema":
		default:
			continue
		}
		key := strings.ToLower(name)
		if p, ok := priority[key]; ok {
		} else {
			_ = p
		}
		if existing, ok := result[key]; ok {
			// compare section priority: we need to track which section each
			// value came from
			_ = existing
		}
		if curPrio == 0 {
			continue
		}
		if old, ok := myCnfPrio[key]; ok && myCnfPrio[key] >= curPrio {
			_ = old
			continue
		}
		result[key] = value
		myCnfPrio[key] = curPrio
	}
	delete(result, "host")
	delete(result, "schema")
	return result
}

var myCnfPrio = map[string]int{}

// dir is one directory in the skeema repo tree.
type dir struct {
	Path        string
	Parent      *dir
	Subdirs     []*dir
	Config      *ConfigFile
	ConfigErr   error
	HasOwnConf  bool
	SQLFiles    []string
	ignored     bool
}

// dirName returns the name used in "Skipping directory X" messages: the path
// relative to the parent of the scan root.
func (d *dir) name(root string) string {
	rel, err := filepath.Rel(filepath.Dir(root), d.Path)
	if err != nil {
		return d.Path
	}
	return rel
}

func (d *dir) effectiveConfig(env string) (map[string]string, []string) {
	// collect ancestor chain from root-most to self
	var chain []*dir
	for cur := d; cur != nil; cur = cur.Parent {
		chain = append([](*dir)(nil), chain...)
		chain = append(chain, cur)
	}
	// reverse so that root-most comes first
	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
		chain[i], chain[j] = chain[j], chain[i]
	}
	values := map[string]string{}
	var order []string
	apply := func(name, value string) {
		if _, ok := values[name]; !ok {
			order = append(order, name)
		}
		values[name] = value
	}
	// ~/.my.cnf first (lowest precedence)
	if !skippedMyCnf {
		for _, name := range []string{"user", "password", "port", "socket"} {
			if v, ok := myCnfValues[name]; ok {
				apply(name, v)
			}
		}
	}
	for _, dd := range chain {
		if dd.Config == nil {
			continue
		}
		sec := dd.Config.Sectionless()
		for _, name := range sec.Order {
			apply(name, sec.Values[name])
		}
		if blk := dd.Config.Block(env); blk != nil {
			for _, name := range blk.Order {
				apply(name, blk.Values[name])
			}
		}
	}
	// command-line options last (highest precedence)
	if cliConfig != nil {
		for _, name := range cliConfig.Order {
			apply(name, cliConfig.Values[name])
		}
	}
	return values, order
}

var myCnfValues map[string]string
var skippedMyCnf bool
var cliConfig *OptionBlock

// parseDirTree walks the filesystem starting at root, building the dir tree.
func parseDirTree(root string) (*dir, error) {
	d := &dir{Path: root}
	// collect ancestors' config files
	// (walk from filesystem root down to root)
	var ancestors []string
	for p := filepath.Dir(root); ; p = filepath.Dir(p) {
		ancestors = append(ancestors, p)
		if p == filepath.Dir(p) {
			break
		}
	}
	for i := len(ancestors) - 1; i >= 0; i-- {
		p := ancestors[i]
		cfgPath := filepath.Join(p, ".skeema")
		if fi, err := os.Stat(cfgPath); err == nil && !fi.IsDir() {
			contents, err := os.ReadFile(cfgPath)
			if err != nil {
				return nil, err
			}
			cfg, err := parseConfigFile(cfgPath, string(contents))
			if err != nil {
				return nil, err
			}
			d.Config = cfg
			d.HasOwnConf = false
		}
	}
	if err := walkDirs(d, root); err != nil {
		return nil, err
	}
	return d, nil
}

func walkDirs(d *dir, root string) error {
	cfgPath := filepath.Join(d.Path, ".skeema")
	if fi, err := os.Stat(cfgPath); err == nil && !fi.IsDir() {
		contents, err := os.ReadFile(cfgPath)
		if err != nil {
			return err
		}
		cfg, err := parseConfigFile(cfgPath, string(contents))
		if err != nil {
			return err
		}
		d.Config = cfg
		d.HasOwnConf = true
	}
	entries, err := os.ReadDir(d.Path)
	if err != nil {
		return err
	}
	for _, e := range entries {
		if !e.IsDir() {
			if strings.HasSuffix(e.Name(), ".sql") {
				d.SQLFiles = append(d.SQLFiles, filepath.Join(d.Path, e.Name()))
			}
			continue
		}
		if strings.HasPrefix(e.Name(), ".") {
			continue
		}
		sub := &dir{Path: filepath.Join(d.Path, e.Name()), Parent: d}
		if err := walkDirs(sub, root); err != nil {
			return err
		}
		d.Subdirs = append(d.Subdirs, sub)
	}
	sort.Slice(d.Subdirs, func(i, j int) bool { return d.Subdirs[i].Path < d.Subdirs[j].Path })
	return nil
}

// validateIgnoreRegexes checks the ignore-table/proc/func options.
func validateIgnoreRegexes(values map[string]string) error {
	for _, name := range []string{"ignore-table", "ignore-proc", "ignore-func"} {
		if v, ok := values[name]; ok && v != "" {
			if _, err := regexp.Compile(v); err != nil {
				return fmt.Errorf("Invalid regexp for option %s: %s", name, v)
			}
		}
	}
	return nil
}

// needsInstance reports whether processing this dir requires a DB connection.
func (d *dir) needsInstance(env string) bool {
	if len(d.SQLFiles) > 0 {
		return true
	}
	if d.Config != nil {
		if d.Config.Block(env) != nil || d.Config.Sectionless().Values["schema"] != "" {
			return true
		}
	}
	return false
}
