// parseHostPort resolves a host value (possibly host:port or IPv6) into the
// host portion and port. Returns the string used for display in error
// messages ("host:port").
func resolveHostPort(host, port string) (hostPart, portPart, display string, isUnix bool, err error) {
	trimmed := strings.TrimSpace(host)
	if trimmed == "" {
		return "", "", "", false, fmt.Errorf("no host")
	}
	if trimmed == "localhost" {
		return "", "", trimmed + ":" + defaultPort, true, nil
	}
	if strings.Contains(trimmed, ":") {
