	}
	for _, fo := range forbiddenConnOpts {
		if _, ok := inst.ConnOpts[fo]; ok {
			return nil, fmt.Errorf("Invalid connection options: connect-options is not allowed to contain %s", fo)
		}
	}
	if v, ok := inst.ConnOpts["ssl-mode"]; ok {
		inst.sslMode = v
	}
	if err := validateSSLMODE(inst.sslMode); err != nil {
		return nil, fmt.Errorf("Invalid connection options: %s", err.Error())
	}

	if host == "" {
		return inst, nil
	}

	hostPart, portPart, display, isUnix, err := resolveHostPort(host, portOpt)
	if err != nil {
		return nil, err
	}
	_ = display
	if isUnix {
		inst.unixSocket = true
		inst.Socket = socketOpt
		if inst.Socket == "" {
			inst.Socket = defaultSocket
		}
		inst.addr = inst.Socket
	} else {
		inst.addr = hostPart + ":" + portPart
	}
	inst.Host = hostPart
	inst.Port = portPart
	// validate DSN
	if err := validateDSN(inst.dsn("")); err != nil {
		return nil, fmt.Errorf("Invalid connection information for %s (DSN=%s): %s", dirPath, inst.maskedDSN(""), err.Error())
	}
	return inst, nil
}

func validateSSLMODE(v string) error {
	switch v {
	case "", "disabled", "preferred", "required":
		return nil
	}
	return fmt.Errorf("Option ssl-mode can only be set to one of these values: %q, %q, %q, %q", "disabled", "preferred", "required", "")
}

// dsn builds the go-sql-driver style DSN.
func (i *Instance) dsn(schema string) string {
	params := map[string]string{}
	// defaults
	params["default_storage_engine"] = "'InnoDB'"
	params["foreign_key_checks"] = "0"
	params["interpolateParams"] = "true"
	params["readTimeout"] = "20s"
	params["timeout"] = "5s"
	params["writeTimeout"] = "5s"
	switch i.sslMode {
	case "disabled":
		params["tls"] = "false"
	case "required":
		params["tls"] = "oldtls"
	default:
		params["allowFallbackToPlaintext"] = "true"
		params["tls"] = "oldtls"
	}
	for k, v := range i.ConnOpts {
		params[k] = v
	}
	keys := make([]string, 0, len(params))
	for k := range params {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var sb strings.Builder
	sb.WriteString(i.User)
	if i.Password != "" {
		sb.WriteString(":" + i.Password)
	}
	if i.unixSocket {
		sb.WriteString("@unix(" + i.addr + ")/")
	} else {
		sb.WriteString("@tcp(" + i.addr + ")/")
	}
	sb.WriteString(schema)
	if len(keys) > 0 {
		sb.WriteString("?")
	}
	for idx, k := range keys {
		if idx > 0 {
			sb.WriteString("&")
		}
		sb.WriteString(k + "=" + urlEncodeValue(params[k]))
	}
	return sb.String()
}

// maskedDSN returns the DSN with the password replaced by asterisks.
func (i *Instance) maskedDSN(schema string) string {
	if i.Password == "" {
		return i.dsn(schema)
	}
	return strings.Replace(i.dsn(schema), i.User+":"+i.Password+"@", i.User+":*****@", 1)
}

func urlEncodeValue(v string) string {
	var sb strings.Builder
	for i := 0; i < len(v); i++ {
		c := v[i]
		if c == '\'' || c == '"' || c == '=' || c == '&' || c == '?' || c == '#' || c == '%' || c == '+' || c == ' ' || c < 0x20 || c > 0x7e {
			sb.WriteString(fmt.Sprintf("%%%02X", c))
			continue
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

// validateDSN mimics the DSN parse errors emitted by the original binary.
func validateDSN(dsn string) error {
	// find params
	qidx := strings.Index(dsn, "?")
	addrPart := dsn
	if qidx >= 0 {
		addrPart = dsn[:qidx]
		for _, kv := range strings.Split(dsn[qidx+1:], "&") {
			if kv == "" {
				continue
			}
			idx := strings.Index(kv, "=")
			if idx < 0 {
				continue
			}
			k, v := kv[:idx], urlDecode(kv[idx+1:])
			switch strings.ToLower(k) {
			case "timeout", "readtimeout", "writetimeout":
				if _, err := parseDuration(v); err != nil {
					return err
				}
			case "tls":
				if !tlsConfigNames[v] {
					return fmt.Errorf("invalid value / unknown config name: %s", v)
				}
			case "maxallowedpacket":
				if _, err := strconv.Atoi(v); err != nil {
					return err
				}
			}
		}
	}
	// extract address
	start := strings.Index(addrPart, "(")
	end := strings.LastIndex(addrPart, ")")
	if start < 0 || end < 0 {
		return fmt.Errorf("default addr for network '%s' unknown", strings.TrimSuffix(addrPart[strings.Index(addrPart, "@")+1:], "/"))
	}
	netName := addrPart[strings.Index(addrPart, "@")+1 : start]
	addr := addrPart[start+1 : end]
	if netName == "" {
		netName = "tcp"
	}
	if netName != "tcp" && netName != "unix" {
		return fmt.Errorf("default addr for network '%s' unknown", netName)
	}
	if netName == "tcp" {
		hostPort := addr
		if !strings.Contains(hostPort, ":") {
			hostPort = hostPort + ":" + defaultPort
		}
		hp, pp, serr := net.SplitHostPort(hostPort)
		if serr != nil {
			return serr
		}
		if n, err := strconv.Atoi(pp); err == nil {
			if n < 0 {
				return fmt.Errorf("invalid port %d supplied", n)
			}
		} else {
			return fmt.Errorf("invalid port %s supplied", pp)
		}
		_ = hp
	}
	return nil
}

func urlDecode(v string) string {
	var sb strings.Builder
	for i := 0; i < len(v); i++ {
		if v[i] == '%' && i+2 < len(v) {
			n, err := strconv.ParseUint(v[i+1:i+3], 16, 8)
			if err == nil {
				sb.WriteByte(byte(n))
				i += 2
				continue
			}
		}
		sb.WriteByte(v[i])
	}
	return sb.String()
}

func parseDuration(s string) (int, error) {
	d, err := timeParseDuration(s)
	if err != nil {
		return 0, err
	}
	return int(d), nil
}

// dial connects to the instance and returns a connection or an error with the
// exact message format used by the original binary.
func (i *Instance) dial() (*conn, error) {
	var c net.Conn
	var err error
	if i.unixSocket {
		c, err = net.DialTimeout("unix", i.addr, 5e9)
	} else {
		c, err = net.DialTimeout("tcp", i.addr, 5e9)
	}
	if err != nil {
		return nil, fmt.Errorf("Unable to connect to %s for %s: %s", i.hostDisplay(), i.dirPath, err.Error())
	}
	nc := &conn{net: c, inst: i}
	if err := nc.handshake(); err != nil {
		c.Close()
		return nil, err
	}
	return nc, nil
}

func (i *Instance) hostDisplay() string {
	if i.unixSocket {
		return "localhost:" + i.addr
	}
	return i.addr
}

