		return 78
	}
	env := environmentName(p)
	root, err := scanRepo(env)
	if err != nil {
		logErrorf("%s", err.Error())
		return 78
	}
	skipped := 0
	for _, d := range dirsInOrder(root) {
		if d.Config == nil {
			continue
		}
		schema := d.schemaOption(env)
		if schema == "" {
			continue
		}
		values, _ := d.effectiveConfig(env)
		if values["host"] == "" && values["workspace"] != "docker" {
			logWarnf("Skipping %s: no host defined for environment %q", d.Path, env)
			logWarnf("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", env)
			continue
		}
		inst, err := NewInstance(d.Path, values)
		if err != nil {
			logErrorf("Skipping %s for %s: %v", instDisplay(values), d.Path, err)
			skipped++
			continue
		}
		_ = inst
		if err := inst.testConnect(); err != nil {
			logErrorf("Skipping %s for %s: %v", instDisplay(values), d.Path, err)
			skipped++
			continue
		}
	}
	if skipped > 0 {
		logErrorf("Skipped %d operation%s due to problem%s", skipped, pluralize(skipped), pluralize(skipped))
		return 2
	}
	return 0
}

func instDisplay(values map[string]string) string {
	inst, err := NewInstance("", values)
	if err != nil {
		return values["host"]
	}
	return inst.hostDisplay()
}

// ---------------------------------------------------------------- pull

func cmdPull(p *parsedArgs) int {
	if err := argCountError("pull", p.args); err != nil {
		logErrorf("%s", err.Error())
		return 78
	}
	env := environmentName(p)
	logUpgradeNotice("format")
	root, err := scanRepo(env)
	if err != nil {
		logErrorf("%s", err.Error())
		return 78
	}
	skipped := 0
	fatal := false
	for _, d := range dirsInOrder(root) {
		if !d.isPullTarget(env) {
			continue
		}
		derr := d.loadConfigError(env)
		if derr == nil {
			derr = checkConfigOptions(d, env)
		}
		if derr != nil {
			logErrorf("Skipping %s: %v", d.Path, derr)
			fatal = true
			continue
		}
		values, _ := d.effectiveConfig(env)
		if values["host"] == "" && values["workspace"] != "docker" {
			logErrorf("Skipping %s: No host defined for environment %q", d.Path, env)
			logErrorf("This command requires a hostname to pull from, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", env)
			fatal = true
			continue
		}
		inst, err := NewInstance(d.Path, values)
		if err != nil {
			logWarnf("Skipping %s: %v", d.Path, err)
			skipped++
			continue
		}
		if err := inst.testConnect(); err != nil {
			logWarnf("Skipping %s: %v", d.Path, err)
			skipped++
			continue
		}
	}
	if fatal {
		return 78
	}
	if skipped > 0 {
		return 1
	}
	return 0
}

// ---------------------------------------------------------------- init

func cmdInit(p *parsedArgs) int {
	if err := argCountError("init", p.args); err != nil {
		logErrorf("%s", err.Error())
		return 78
	}
	host := p.value("host")
	if host == "" {
		logErrorf("Option --host must be supplied on the command-line")
		return 78
	}
	dirName := p.value("dir")
	if dirName == "" {
		dirName = host
	}
	if !filepath.IsAbs(dirName) {
		dirName = filepath.Join(".", dirName)
	}
	if err := os.MkdirAll(dirName, 0777); err != nil {
		logErrorf("Cannot create dir %s: %v", dirName, err)
		return 73
	}
	env := environmentName(p)
	values, _ := effectiveConfigForPath(dirName, env)
	inst, err := NewInstance(dirName, values)
	if err != nil {
		logErrorf("%s", err.Error())
		return 78
	}
	if err := inst.testConnect(); err != nil {
		logErrorf("%s", err.Error())
		return 2
	}
	// Connection succeeded: write out the filesystem representation.
	return initWrite(p, inst, dirName, env)
}

// effectiveConfigForPath computes the effective config for an arbitrary path
// (used by init, which may operate outside the scanned tree).
func effectiveConfigForPath(path, env string) (map[string]string, []string) {
	// build a chain of ancestor .skeema files, root-most first
	var files []*ConfigFile
	abs, _ := filepath.Abs(path)
	var ancestors []string
	for p := abs; ; p = filepath.Dir(p) {
		cfgPath := filepath.Join(p, ".skeema")
		if fi, err := os.Stat(cfgPath); err == nil && !fi.IsDir() {
			contents, err := os.ReadFile(cfgPath)
			if err == nil {
				cfg, err := parseConfigFile(cfgPath, string(contents))
				if err == nil {
					files = append(files, cfg)
				}
			}
		}
		if p == filepath.Dir(p) {
			break
		}
		ancestors = append(ancestors, p)
	}
	// reverse: root-most first
	for i, j := 0, len(files)-1; i < j; i, j = i+1, j-1 {
		files[i], files[j] = files[j], files[i]
	}
	values := map[string]string{}
	var order []string
	apply := func(name, value string) {
		if _, ok := values[name]; !ok {
			order = append(order, name)
		}
		values[name] = value
	}
	if !skippedMyCnf {
		for _, name := range []string{"user", "password", "port", "socket"} {
			if v, ok := myCnfValues[name]; ok {
				apply(name, v)
			}
		}
	}
	for _, f := range files {
		sec := f.Sectionless()
		for _, name := range sec.Order {
			apply(name, sec.Values[name])
		}
		if blk := f.Block(env); blk != nil {
			for _, name := range blk.Order {
				apply(name, blk.Values[name])
			}
		}
	}
	if cliConfig != nil {
		for _, name := range cliConfig.Order {
			apply(name, cliConfig.Values[name])
		}
	}
	return values, order
}

// ---------------------------------------------------------------- add-environment

func cmdAddEnvironment(p *parsedArgs) int {
	if len(p.args) < commandMinArgs["add-environment"] {
		logErrorf("Too few positional args supplied on command line; command %s requires at least %d args", "add-environment", commandMinArgs["add-environment"])
		return 78
	}
	if err := argCountError("add-environment", p.args); err != nil {
		logErrorf("%s", err.Error())
		return 78
	}
	envName := p.args[0]
	dirName := p.value("dir")
	if dirName == "" {
		dirName = "."
	}
	if fi, err := os.Stat(dirName); err != nil || !fi.IsDir() {
		logErrorf("In add-environment, --dir must refer to a directory that already exists")
		return 78
	}
	cfgPath := filepath.Join(dirName, ".skeema")
	contents, err := os.ReadFile(cfgPath)
	if err != nil {
		logErrorf("Dir %s does not have an existing .skeema file! Can only use `skeema add-environment` on a dir previously created by `skeema init`", dirName)
		return 78
	}
	absDir, _ := filepath.Abs(dirName)
	cfg, err := parseConfigFile(cfgPath, string(contents))
	if err != nil {
		logErrorf("%s", err.Error())
		return 78
	}
	if envName == "" {
		logErrorf("Environment name %q is invalid", envName)
		return 78
	}
	if cfg.Block(envName) != nil {
		logErrorf("Environment name %q already defined in %s", envName, cfgPath)
		return 78
	}
	host := p.value("host")
	if host == "" {
		logErrorf("`skeema add-environment` requires --host to be supplied on command-line")
		return 78
	}
	// Determine the effective config for the new environment, then connect to
	// the server to determine its flavor/version.
	values, _ := effectiveConfigForPath(absDir, envName)
	values["host"] = host
	if p.has("port") {
		values["port"] = p.value("port")
	}
	if p.has("socket") {
		values["socket"] = p.value("socket")
	}
	inst, err := NewInstance(absDir, values)
	flavorErr := err
	if err == nil {
		if err := inst.testConnect(); err != nil {
			flavorErr = err
		} else {
			flavorErr = nil
		}
	}
	if flavorErr != nil {
		logWarnf("Unable to automatically determine database server's vendor/version. To set manually, use the \"flavor\" option in %s", cfgPath)
	}
	// write the new section
	newSection := writeSection(envName, p, values, cfgPath)
	if err := appendSection(cfgPath, cfg, newSection); err != nil {
		logErrorf("Unable to write to %s: %v", cfgPath, err)
		return 78
	}
	logInfof("Added environment [%s] to %s", envName, cfgPath)
	return 0
}

// writeSection builds the option lines for the new environment section.
func writeSection(envName string, p *parsedArgs, values map[string]string, cfgPath string) []string {
	host := values["host"]
	socket := ""
	if p.has("socket") {
		socket = p.value("socket")
	}
	var lines []string
	if host == "localhost" && socket != "" {
		lines = append(lines, "host="+host)
		lines = append(lines, "socket="+socket)
	} else {
		port := values["port"]
		if port == "" {
			port = "3306"
		}
		n, err := strconv.Atoi(port)
		if err != nil || n == 0 {
			port = "3306"
		}
		lines = append(lines, "host="+host)
		lines = append(lines, "port="+port)
	}
	extra := map[string]string{}
	if p.has("user") {
		extra["user"] = p.value("user")
	}
	if p.has("connect-options") {
		extra["connect-options"] = p.value("connect-options")
	}
	if p.has("ssl-mode") {
		extra["ssl-mode"] = p.value("ssl-mode")
	}
	if len(extra) > 0 {
		keys := make([]string, 0, len(extra))
		for k := range extra {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			lines = append(lines, k+"="+extra[k])
		}
	}
	// sort all lines alphabetically
	sort.Strings(lines)
	return lines
}
