package main

import (
	"crypto/sha1"
	"encoding/binary"
	"errors"
	"fmt"
	"net"
)

// conn is a minimal MySQL client connection, sufficient for the queries the
// tool issues (metadata lookups, schema creation, etc).
type conn struct {
	net     net.Conn
	inst    *Instance
	seq     byte
	serverVersion string
	caps    uint32
}

func (c *conn) readPacket() ([]byte, error) {
	header := make([]byte, 4)
	if _, err := readFull(c.net, header); err != nil {
		return nil, err
	}
	length := int(uint32(header[0]) | uint32(header[1])<<8 | uint32(header[2])<<16)
	c.seq = header[3] + 1
	payload := make([]byte, length)
	if _, err := readFull(c.net, payload); err != nil {
		return nil, err
	}
	return payload, nil
}

func readFull(c net.Conn, buf []byte) (int, error) {
	total := 0
	for total < len(buf) {
		n, err := c.Read(buf[total:])
		if err != nil {
			return total, err
		}
		if n == 0 {
			return total, errors.New("unexpected EOF")
		}
		total += n
	}
	return total, nil
}

func (c *conn) writePacket(payload []byte) error {
	header := make([]byte, 4)
	length := len(payload)
	header[0] = byte(length)
	header[1] = byte(length >> 8)
	header[2] = byte(length >> 16)
	header[3] = c.seq
	c.seq++
	if _, err := c.net.Write(header); err != nil {
		return err
	}
	if _, err := c.net.Write(payload); err != nil {
		return err
	}
	return nil
}

// handshake performs the initial handshake and authentication.
func (c *conn) handshake() error {
	pkt, err := c.readPacket()
	if err != nil {
		return err
	}
	if len(pkt) == 0 {
		return fmt.Errorf("Unable to connect to %s for %s: unexpected EOF", c.inst.hostDisplay(), c.inst.dirPath)
	}
	if pkt[0] == 0xff {
		// error packet
		return c.errorPacket(pkt)
	}
	if pkt[0] != 0x0a {
		return fmt.Errorf("Unable to connect to %s for %s: unsupported protocol version %d", c.inst.hostDisplay(), c.inst.dirPath, pkt[0])
	}
	pos := 1
	// server version (NUL terminated)
	end := pos
	for end < len(pkt) && pkt[end] != 0 {
		end++
	}
	c.serverVersion = string(pkt[pos:end])
	pos = end + 1
	pos += 4 // connection id
	var seed []byte
	if pos+8 <= len(pkt) {
		seed = append(seed, pkt[pos:pos+8]...)
	}
	pos += 8 + 1 // filler
	caps := uint32(pkt[pos]) | uint32(pkt[pos+1])<<8
	pos += 2
	if pos < len(pkt) {
		c.charset = int8(pkt[pos])
	}
	pos += 2 // status flags
	if pos+2 <= len(pkt) {
		caps |= uint32(pkt[pos]) | uint32(pkt[pos+1])<<8<<16
		pos += 2
	}
	c.caps = caps
	if pos < len(pkt) {
		authLen := int(pkt[pos])
		pos++
		if authLen == 0 {
			// 4.0 handshake: NUL terminated seed
			for pos < len(pkt) && pkt[pos] != 0 {
				seed = append(seed, pkt[pos])
				pos++
			}
		} else {
			if pos+13 <= len(pkt) {
				seed = append(seed, pkt[pos:pos+13]...)
			}
			pos += 13
		}
		if pos < len(pkt) {
			seed = append(seed, pkt[pos:]...)
		}
	}
	// strip trailing NUL
	for len(seed) > 0 && seed[len(seed)-1] == 0 {
		seed = seed[:len(seed)-1]
	}
	// send handshake response
	resp, err := c.buildHandshakeResponse(seed)
	if err != nil {
		return err
	}
	if err := c.writePacket(resp); err != nil {
		return err
	}
	// auth result
	pkt, err = c.readPacket()
	if err != nil {
		return err
	}
	if pkt[0] == 0xff {
		return c.errorPacket(pkt)
	}
	if pkt[0] == 0xfe {
		// auth switch request: re-authenticate with the new seed
		if len(pkt) > 1 {
			newSeed := pkt[1:]
			if len(newSeed) > 0 && newSeed[len(newSeed)-1] == 0 {
				newSeed = newSeed[:len(newSeed)-1]
			}
			resp, err := c.buildAuthSwitch(newSeed)
			if err != nil {
				return err
			}
			if err := c.writePacket(resp); err != nil {
				return err
			}
			pkt, err = c.readPacket()
			if err != nil {
				return err
			}
			if pkt[0] == 0xff {
				return c.errorPacket(pkt)
			}
		}
	}
	return nil
}

func (c *conn) errorPacket(pkt []byte) error {
	if len(pkt) < 3 {
		return fmt.Errorf("Unable to connect to %s for %s: malformed error packet", c.inst.hostDisplay(), c.inst.dirPath)
	}
	errno := binary.LittleEndian.Uint16(pkt[1:3])
	msg := ""
	if len(pkt) > 3 && pkt[3] == '#' {
		// sql state
		if len(pkt) > 8 {
			msg = string(pkt[9:])
		}
	} else {
		msg = string(pkt[3:])
	}
	return fmt.Errorf("%s (errno %d)", msg, errno)
}

func (c *conn) buildHandshakeResponse(seed []byte) ([]byte, error) {
	clientCaps := uint32(0x00000001) // CLIENT_LONG_PASSWORD
	clientCaps |= 0x00000200         // CLIENT_PROTOCOL_41
	clientCaps |= 0x00008000         // CLIENT_SECURE_CONNECTION
	clientCaps |= 0x00080000         // CLIENT_PLUGIN_AUTH
	clientCaps |= 0x00200000         // CLIENT_CONNECT_WITH_DB? no
	clientCaps |= 0x00000008         // CLIENT_CONNECT_WITH_DB
	clientCaps |= 0x00000020         // CLIENT_PROTOCOL_41 already
	clientCaps |= 0x00000004         // CLIENT_LONG_FLAG
	clientCaps |= 0x00000400         // CLIENT_TRANSACTIONS
	clientCaps |= 0x00010000         // CLIENT_MULTI_RESULTS
	clientCaps |= 0x08000000         // CLIENT_PLUGIN_AUTH_LEN_ENC
	maxPacket := uint32(0x1000000)
	buf := make([]byte, 0, 128)
	buf = append(buf, byte(clientCaps), byte(clientCaps>>8), byte(clientCaps>>16), byte(clientCaps>>24))
	buf = append(buf, byte(maxPacket), byte(maxPacket>>8), byte(maxPacket>>16), byte(maxPacket>>24))
	buf = append(buf, 0x21) // utf8_general_ci
	buf = append(buf, make([]byte, 23)...)
	buf = append(buf, []byte(c.inst.User)...)
	buf = append(buf, 0)
	auth := scramblePassword(c.inst.Password, seed)
	buf = append(buf, byte(len(auth)))
	buf = append(buf, auth...)
	buf = append(buf, []byte("mysql_native_password")...)
	buf = append(buf, 0)
	return buf, nil
}

func (c *conn) buildAuthSwitch(seed []byte) ([]byte, error) {
	auth := scramblePassword(c.inst.Password, seed)
	buf := append([]byte{}, auth...)
	buf = append(buf, 0)
	return buf, nil
}

// scramblePassword computes the mysql_native_password scramble.
func scramblePassword(password string, seed []byte) []byte {
	if password == "" {
		return nil
	}
	h1 := sha1.Sum([]byte(password))
	h2 := sha1.Sum(h1[:])
	h3 := sha1.Sum(append(append([]byte{}, seed...), h2[:]...))
	result := make([]byte, sha1.Size)
	for i := range result {
		result[i] = h1[i] ^ h3[i]
	}
	return result
}

// query executes a statement and discards any result set.
func (c *conn) query(q string) error {
	if err := c.writePacket(append([]byte{0x00}, []byte(q)...)); err != nil {
		return err
	}
	pkt, err := c.readPacket()
	if err != nil {
		return err
	}
	if pkt[0] == 0xff {
		return c.errorPacket(pkt)
	}
	if pkt[0] == 0x00 || pkt[0] == 0xfe {
		return nil
	}
	// result set: read all rows
	colCount := int(pkt[0])
	for i := 0; i < colCount; i++ {
		if _, err := c.readPacket(); err != nil {
			return err
		}
	}
	for {
		pkt, err := c.readPacket()
		if err != nil {
			return err
		}
		if pkt[0] == 0xfe && len(pkt) < 9 {
			return nil
		}
		if pkt[0] == 0xff {
			return c.errorPacket(pkt)
		}
	}
}

func (c *conn) close() {
	c.net.Close()
}

