package main

import (
	"os"
	"strings"
)

// parsedObject represents a CREATE statement found in a .sql file.
type parsedObject struct {
	Type       string // table, procedure, function
	Schema     string
	Name       string
	CreateStmt string
}

func parseDirObjects(d *dir) ([]parsedObject, error) {
	var objects []parsedObject
	for _, path := range d.SQLFiles {
		contents, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		objs, err := parseSQLFile(path, string(contents))
		if err != nil {
			return nil, err
		}
		objects = append(objects, objs...)
	}
	return objects, nil
}

// parseSQLFile extracts CREATE TABLE/PROCEDURE/FUNCTION statements from a
// .sql file.
func parseSQLFile(path, contents string) ([]parsedObject, error) {
	var objects []parsedObject
	for _, stmt := range splitStatements(contents) {
		trimmed := strings.TrimSpace(stmt)
		if trimmed == "" {
			continue
		}
		lower := strings.ToLower(trimmed)
		var typ string
		switch {
		case strings.HasPrefix(lower, "create table"), strings.HasPrefix(lower, "create  table"):
			typ = "table"
		case strings.HasPrefix(lower, "create procedure"), strings.HasPrefix(lower, "create  procedure"):
			typ = "procedure"
		case strings.HasPrefix(lower, "create function"), strings.HasPrefix(lower, "create  function"):
			typ = "function"
		default:
			continue
		}
		name := objectName(trimmed)
		objects = append(objects, parsedObject{Type: typ, Name: name, CreateStmt: trimmed})
	}
	return objects, nil
}

// splitStatements splits a SQL file into individual statements on semicolons,
// respecting quoted strings and comments.
func splitStatements(contents string) []string {
	var out []string
	var sb strings.Builder
	var quote byte
	var inLineComment bool
	var inBlockComment bool
	for i := 0; i < len(contents); i++ {
		c := contents[i]
		if inLineComment {
			if c == '\n' {
