package main

import (
	"os"
	"strings"
)

// parsedObject represents a CREATE statement found in a .sql file.
type parsedObject struct {
	Type       string // table, procedure, function
	Schema     string
	Name       string
	CreateStmt string
}

func parseDirObjects(d *dir) ([]parsedObject, error) {
	var objects []parsedObject
	for _, path := range d.SQLFiles {
		contents, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		objs, err := parseSQLFile(path, string(contents))
		if err != nil {
			return nil, err
		}
		objects = append(objects, objs...)
	}
	return objects, nil
}

// parseSQLFile extracts CREATE TABLE/PROCEDURE/FUNCTION statements from a
// .sql file.
func parseSQLFile(path, contents string) ([]parsedObject, error) {
	var objects []parsedObject
	for _, stmt := range splitStatements(contents) {
		trimmed := strings.TrimSpace(stmt)
		if trimmed == "" {
			continue
		}
		lower := strings.ToLower(trimmed)
		var typ string
		switch {
		case strings.HasPrefix(lower, "create table"), strings.HasPrefix(lower, "create  table"):
			typ = "table"
		case strings.HasPrefix(lower, "create procedure"), strings.HasPrefix(lower, "create  procedure"):
			typ = "procedure"
		case strings.HasPrefix(lower, "create function"), strings.HasPrefix(lower, "create  function"):
			typ = "function"
		default:
			continue
		}
		name := objectName(trimmed)
		objects = append(objects, parsedObject{Type: typ, Name: name, CreateStmt: trimmed})
	}
	return objects, nil
}

// splitStatements splits a SQL file into individual statements on semicolons,
// respecting quoted strings and comments.
func splitStatements(contents string) []string {
	var out []string
	var sb strings.Builder
	var quote byte
	var inLineComment bool
	var inBlockComment bool
	for i := 0; i < len(contents); i++ {
		c := contents[i]
		if inLineComment {
			if c == '\n' {
				inLineComment = false
				sb.WriteByte(c)
			}
			continue
		}
		if inBlockComment {
			if c == '*' && i+1 < len(contents) && contents[i+1] == '/' {
				inBlockComment = false
				i++
			}
			continue
		}
		if quote == 0 {
			if c == '-' && i+1 < len(contents) && contents[i+1] == '-' {
				inLineComment = true
				continue
			}
			if c == '#' {
				inLineComment = true
				continue
			}
			if c == '/' && i+1 < len(contents) && contents[i+1] == '*' {
				inBlockComment = true
				i++
				continue
			}
			if c == '\'' || c == '"' || c == '`' {
				quote = c
				sb.WriteByte(c)
				continue
			}
			if c == ';' {
				out = append(out, sb.String())
				sb.Reset()
				continue
			}
			sb.WriteByte(c)
			continue
		}
		sb.WriteByte(c)
		if c == quote {
			if quote == '`' || quote == '\'' || quote == '"' {
				// handle doubled quotes
				if i+1 < len(contents) && contents[i+1] == quote {
					sb.WriteByte(contents[i+1])
					i++
					continue
				}
			}
			quote = 0
		}
	}
	if strings.TrimSpace(sb.String()) != "" {
		out = append(out, sb.String())
	}
	return out
}

// objectName extracts the object name from a CREATE statement.
func objectName(stmt string) string {
	lower := strings.ToLower(stmt)
	idx := strings.Index(lower, "table")
	if idx < 0 {
		if i := strings.Index(lower, "procedure"); i >= 0 {
			idx = i + len("procedure")
		} else if i := strings.Index(lower, "function"); i >= 0 {
			idx = i + len("function")
		}
	} else {
		idx += len("table")
	}
	if idx < 0 || idx >= len(stmt) {
		return ""
	}
	rest := strings.TrimSpace(stmt[idx:])
	if strings.HasPrefix(lower, "create or replace") || strings.Contains(lower[:30], "if not exists") {
		if i := strings.Index(strings.ToLower(rest), "exists"); i >= 0 {
			rest = strings.TrimSpace(rest[i+len("exists"):])
		}
	}
	if rest == "" {
		return ""
	}
	if rest[0] == '`' {
		end := strings.Index(rest[1:], "`")
		if end < 0 {
			return rest
		}
		return rest[1 : 1+end]
	}
	for i := 0; i < len(rest); i++ {
		if rest[i] == ' ' || rest[i] == '\n' || rest[i] == '\t' || rest[i] == '(' {
			return rest[:i]
		}
	}
	return rest
}
