package main

import (
	"fmt"
	"strconv"
	"strings"
)

// timeParseDuration is a minimal reimplementation of time.ParseDuration with
// identical error messages.
func timeParseDuration(s string) (int64, error) {
	orig := s
	var d int64
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	if s == "" || s == "0" {
		if s == "" {
			return 0, fmt.Errorf("time: invalid duration %q", orig)
		}
		return 0, nil
	}
	unit := func(u string) (int64, bool) {
		switch u {
		case "ns":
			return 1, true
		case "us", "µs", "μs":
			return 1000, true
		case "ms":
			return 1000000, true
		case "s":
			return 1000000000, true
		case "m":
			return 60000000000, true
		case "h":
			return 3600000000000, true
		}
		return 0, false
	}
	for s != "" {
		// integer part
		i := 0
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i == 0 {
			return 0, fmt.Errorf("time: invalid duration %q", orig)
		}
		v, err := strconv.ParseInt(s[:i], 10, 64)
		if err != nil {
			return 0, fmt.Errorf("time: invalid duration %q", orig)
		}
		s = s[i:]
		// fractional part
		frac := int64(0)
		fscale := int64(1)
		if len(s) > 0 && s[0] == '.' {
			s = s[1:]
			j := 0
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				j++
			}
			if j == 0 {
				return 0, fmt.Errorf("time: invalid duration %q", orig)
			}
			fs := "1"
			for k := 0; k < j; k++ {
				fs += "0"
			}
			fv, err := strconv.ParseInt(s[:j], 10, 64)
			if err != nil {
				return 0, fmt.Errorf("time: invalid duration %q", orig)
			}
			fscale, _ = strconv.ParseInt(fs, 10, 64)
			frac = fv
			s = s[j:]
		}
		// unit
		j := 0
		for j < len(s) && !(s[j] >= '0' && s[j] <= '9') && s[j] != '.' {
			j++
		}
		if j == 0 {
			return 0, fmt.Errorf("time: missing unit in duration %q", orig)
		}
		u := s[:j]
		s = s[j:]
		mul, ok := unit(u)
		if !ok {
			return 0, fmt.Errorf("time: unknown unit %q in duration %q", u, orig)
		}
		if v > (1<<63-1)/mul {
			return 0, fmt.Errorf("time: invalid duration %q", orig)
		}
		v *= mul
		if frac > 0 {
			frac = frac * mul / fscale
			v += frac
			if v < 0 {
				return 0, fmt.Errorf("time: invalid duration %q", orig)
			}
		}
		d += v
		if d < 0 {
			return 0, fmt.Errorf("time: invalid duration %q", orig)
		}
	}
	if neg {
		d = -d
	}
	return d, nil
}
