package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// initWrite writes the filesystem representation of an instance's schemas.
func initWrite(p *parsedArgs, inst *Instance, dirName, env string) int {
	baseDir := dirName
	configPath := filepath.Join(baseDir, ".skeema")
	if _, err := os.Stat(configPath); err == nil {
		logErrorf("Refusing to overwrite existing %s", configPath)
		return 78
	}
	// With --schema, only that schema is imported into the base dir; otherwise
	// a subdir per schema is created.
	var schemas []string
	schemaOnly := p.value("schema")
	if schemaOnly != "" {
		schemas = []string{schemaOnly}
	} else {
		schemas = inst.listSchemas()
	}
	lines := []string{}
	if inst.unixSocket {
		lines = append(lines, "host=localhost", "socket="+inst.Socket)
	} else {
		lines = append(lines, "host="+inst.Host, "port="+inst.Port)
	}
	if p.has("user") {
		lines = append(lines, "user="+p.value("user"))
	}
	sort.Strings(lines)
	var sb strings.Builder
	for _, l := range lines {
		sb.WriteString(l + "\n")
	}
	if err := os.WriteFile(configPath, []byte(sb.String()), 0666); err != nil {
		logErrorf("Unable to write to %s: %v", configPath, err)
		return 78
	}
	for _, schema := range schemas {
		schemaDir := filepath.Join(baseDir, schema)
		if schemaOnly != "" {
			schemaDir = baseDir
		}
		if err := os.MkdirAll(schemaDir, 0777); err != nil {
			logErrorf("Cannot create dir %s: %v", schemaDir, err)
			return 73
		}
		if schemaOnly == "" {
			scfg := filepath.Join(schemaDir, ".skeema")
			if _, err := os.Stat(scfg); err != nil {
				if err := os.WriteFile(scfg, []byte("schema="+schema+"\n"), 0666); err != nil {
					logErrorf("Unable to write to %s: %v", scfg, err)
					return 78
				}
			}
		}
		if err := writeSchemaFiles(inst, schema, schemaDir, p); err != nil {
			logErrorf("%s", err.Error())
			return 2
		}
	}
	return 0
}

// writeSchemaFiles writes *.sql files for a schema into dir.
func writeSchemaFiles(inst *Instance, schema, dir string, p *parsedArgs) error {
	tables, err := inst.listTables(schema)
	if err != nil {
		return err
	}
	var sb strings.Builder
	for _, t := range tables {
		sb.WriteString(t + "\n\n")
	}
	path := filepath.Join(dir, "tables.sql")
	if len(tables) > 0 {
		if err := os.WriteFile(path, []byte(sb.String()), 0666); err != nil {
			return fmt.Errorf("Unable to write to %s: %v", path, err)
		}
	}
	return nil
}

