// appendSection writes a new environment section to a .skeema file, rewriting
// the file in canonical form.
func appendSection(path string, cfg *ConfigFile, lines []string) error {
	var sb strings.Builder
	// sectionless block
	sec := cfg.Sectionless()
	for _, name := range sec.Order {
		if name == "" {
