    m=re.match(r'^\t"(\S+)": \{$', line)
    if m: cur=m.group(1).strip('"'); cmdopts[cur]=[]; continue
    m=re.match(r'^\t\t\{name: "([^"]+)", short: "([^"]*)",.*desc: "(.*)", def: "([^"]*)", valid: "([^"]*)", dep: "(.*)"\},$', line)
    if m and cur:
        cmdopts[cur].append(dict(name=m.group(1), desc=m.group(2)))
# for each command help file, compute desc column per option
cmdfiles={'add-environment':'/tmp/h/add-environment.txt','diff':'/tmp/h/diff.txt','format':'/tmp/h/format.txt','init':'/tmp/h/init.txt','lint':'/tmp/h/lint.txt','pull':'/tmp/h/pull.txt','push':'/tmp/h/push.txt','version':'/tmp/hx'}
