        m=re.match(r'^  (?:-(\w|\?), |    )?(--[^ ]+)(.*)$', l)
        if not m: continue
        nm=m.group(2).replace('--','').replace('[skip-]','').replace('[=value]','')
        # find desc
        d=None
        for o in cmdopts[c]:
            if o['name']==nm: d=o['desc'].replace('\\"','"'); break
        if d is None:
            # hidden option: find desc from any command
            for cc in cmdopts:
                for o in cmdopts[cc]:
                    if o['name']==nm: d=o['desc'].replace('\\"','"'); break
                if d: break
        if not d: continue
        idx=l.find(d)
        if idx < 0: 
            print('   MISS', c, nm, repr(d[:40])); continue
        cols.setdefault(nm, idx)
    # group by group
    print(c, 'desc columns:', sorted(set(cols.values())))
