new = '''// resolveHostPort resolves a host value (possibly host:port or IPv6) into the
// host portion and port.
func resolveHostPort(host, portOpt string) (hostPart, portPart string, isUnix bool, err error) {
	trimmed := strings.TrimSpace(host)
	if trimmed == "" {
		return "", "", false, fmt.Errorf("no host")
	}
	if trimmed == "localhost" {
		return "", "", true, nil
	}
	if strings.Contains(trimmed, ":") {
		hp, pp, serr := net.SplitHostPort(trimmed)
		if serr != nil {
			if strings.HasSuffix(trimmed, "]") {
				hp = trimmed
				pp = ""
			} else {
				return "", "", false, serr
			}
		}
		port := portOpt
		if pp != "" {
			n, aerr := strconv.Atoi(pp)
			if aerr != nil {
				return "", "", false, aerr
			}
			if n <= 0 {
				return "", "", false, fmt.Errorf("invalid port %d supplied", n)
			}
			port = strconv.Itoa(n)
		} else {
			if n, aerr := strconv.Atoi(port); aerr == nil && n != 0 {
				port = strconv.Itoa(n)
			} else {
				port = defaultPort
			}
		}
		if strings.HasPrefix(trimmed, "[") && !strings.HasPrefix(hp, "[") {
			hp = "[" + hp + "]"
		}
		return hp, port, false, nil
	}
	port := portOpt
	if n, aerr := strconv.Atoi(port); aerr == nil && n != 0 {
		port = strconv.Itoa(n)
	} else {
		port = defaultPort
	}
	return trimmed, port, false, nil
}

'''
