func NewInstance(dirPath string, values map[string]string) (*Instance, error) {
	inst := &Instance{dirPath: dirPath, ConnOpts: map[string]string{}}
	inst.User = values["user"]
	inst.Password = values["password"]
	if inst.User == "" {
		inst.User = "root"
	}
	host := values["host"]
	portOpt := values["port"]
	socketOpt := values["socket"]
	inst.sslMode = values["ssl-mode"]

	for _, kv := range strings.Split(values["connect-options"], ",") {
		if kv == "" {
			continue
		}
		idx := strings.Index(kv, "=")
		if idx < 0 {
			continue
		}
		key := kv[:idx]
		val := kv[idx+1:]
		if strings.EqualFold(key, "tls") {
			logWarnf("Setting the tls option in connect-options is deprecated, and will no longer be allowed in Skeema v2. Use the dedicated ssl-mode option instead.")
		}
		inst.ConnOpts[key] = val
	}
	for _, fo := range forbiddenConnOpts {
		if _, ok := inst.ConnOpts[fo]; ok {
			return nil, fmt.Errorf("Invalid connection options: connect-options is not allowed to contain %s", fo)
		}
	}
	if v, ok := inst.ConnOpts["ssl-mode"]; ok {
		inst.sslMode = v
	}
	if err := validateSSLMODE(inst.sslMode); err != nil {
		return nil, fmt.Errorf("Invalid connection options: %s", err.Error())
	}

	if host == "" {
		return inst, nil
	}

	hostPart, portPart, isUnix, err := resolveHostPort(host, portOpt)
	if err != nil {
		return nil, err
	}
	if isUnix {
		inst.unixSocket = true
		inst.Socket = socketOpt
		if inst.Socket == "" {
			inst.Socket = defaultSocket
		}
		inst.addr = inst.Socket
	} else {
		inst.addr = hostPart + ":" + portPart
		inst.Host = hostPart
		inst.Port = portPart
	}
	if err := validateDSN(inst.dsn("")); err != nil {
		return nil, fmt.Errorf("Invalid connection information for %s (DSN=%s): %s", dirPath, inst.maskedDSN(""), err.Error())
	}
	return inst, nil
}

func validateSSLMODE(v string) error {
	switch v {
	case "", "disabled", "preferred", "required":
		return nil
	}
	return fmt.Errorf("Option ssl-mode can only be set to one of these values: %q, %q, %q, %q", "disabled", "preferred", "required", "")
}

