// buildCLIConfig creates the option block from the command-line options.
func buildCLIConfig(p *parsedArgs, cmdName string) *OptionBlock {
	blk := &OptionBlock{Values: map[string]string{}}
	opts, ok := commandOptions[cmdName]
	if !ok {
		return blk
	}
	for _, o := range opts {
		rec, ok := p.opts[o.name]
		if !ok || !rec.set {
			continue
		}
		if o.val && !o.optval {
			blk.set(o.name, rec.value)
			continue
		}
		if o.val && o.optval {
			blk.set(o.name, rec.value)
			continue
		}
		// boolean
		truthy := parseBool(rec.value)
		if rec.skip {
			truthy = !truthy
		}
		if truthy {
			blk.set(o.name, "1")
		} else {
			blk.set(o.name, "0")
