package main

import (
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

// wrapperVars returns the template variables available to host-wrapper.
func wrapperVars(d *dir, env string, values map[string]string) map[string]string {
	return map[string]string{
		"host":        values["host"],
		"schema":      d.schemaOption(env),
		"environment": env,
		"dirpath":     d.Path,
	}
}

// expandWrapper expands template variables in the wrapper command line and
// splits it into tokens (shell-style). Empty tokens are dropped.
func expandWrapper(wrap string, vars map[string]string) ([]string, error) {
	var tokens []string
	i := 0
	n := len(wrap)
	for i < n {
		for i < n && (wrap[i] == ' ' || wrap[i] == '\t' || wrap[i] == '\n') {
			i++
		}
		if i >= n {
			break
		}
		var sb strings.Builder
		var quote byte
		for i < n {
			c := wrap[i]
			if quote != 0 {
				if c == quote {
					quote = 0
					i++
					continue
				}
				sb.WriteByte(c)
				i++
				continue
			}
			if c == '"' || c == '\'' {
				quote = c
				i++
				continue
			}
			if c == ' ' || c == '\t' || c == '\n' {
				break
			}
			if c == '{' {
				end := strings.IndexByte(wrap[i:], '}')
				if end < 0 {
					return nil, fmt.Errorf("Variable name missing closing brace: %s", wrap[i:])
				}
				name := wrap[i+1 : i+end]
				val, ok := vars[strings.ToLower(name)]
				if !ok {
					return nil, fmt.Errorf("Unknown variable %s", strings.ToUpper(name))
				}
				sb.WriteString(val)
				i += end + 1
				continue
			}
			sb.WriteByte(c)
			i++
		}
		tok := sb.String()
		if tok != "" {
			tokens = append(tokens, tok)
		}
	}
	return tokens, nil
}

// wrapperHosts runs the host-wrapper command and returns the host names it
// printed on stdout.
func wrapperHosts(tokens []string) ([]string, error) {
	cmdline := strings.Join(tokens, " ")
	cmd := exec.Command("sh", "-c", cmdline)
	out, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	var hosts []string
	for _, line := range strings.Split(string(out), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		hosts = append(hosts, line)
	}
	return hosts, nil
}

// wrapperInstance builds an Instance from a wrapper-provided host line.
func wrapperInstance(dirPath, hostLine, portOpt string, values map[string]string) (*Instance, error) {
	host := hostLine
	port := ""
	if idx := strings.LastIndex(host, ":"); idx >= 0 && !strings.Contains(host[idx:], "]") {
		port = host[idx+1:]
		host = host[:idx]
	}
	if port != "" {
		if portOpt != "" {
			configured, err := strconv.Atoi(strings.TrimSpace(portOpt))
			if err == nil {
				supplied, err2 := strconv.Atoi(port)
				if err2 == nil && supplied != configured {
					return nil, fmt.Errorf("Port was supplied as %d inside hostname %s but as %d in option file", supplied, hostLine, configured)
				}
			}
		}
	} else if portOpt != "" {
		port = strings.TrimSpace(portOpt)
	}
	if port == "" {
		port = defaultPort
	}
	vals := map[string]string{}
	for k, v := range values {
		vals[k] = v
	}
	vals["host"] = host
	vals["port"] = port
	delete(vals, "socket")
	return NewInstance(dirPath, vals)
}
