function.arguments:
{"command": "cd /workspace && cat > sqlparse.go <<'GOEOF'
package main

import (
	"os"
	"strings"
)

// sqlObject represents a CREATE statement found in a .sql file.
type sqlObject struct {
	Type   string // table, procedure, function
	Name   string
	Line   int
	Col    int
	Stmt   string
}

// sqlWarning represents an unparseable or unsupported statement.
type sqlWarning struct {
	File string
	Line int
	Col  int
}

// parseSQLFile extracts objects from a .sql file. Objects are returned along
// with warnings for statements that could not be parsed.
func parseSQLFile(path, contents string) ([]sqlObject, []sqlWarning, error) {
	var objects []sqlObject
	var warnings []sqlWarning
	for _, st := range splitStatements(contents) {
		if st.text == "" {
			continue
		}
		obj, warn := classifyStatement(st.text, st.line, st.col)
		if obj != nil {
			objects = append(objects, *obj)
			continue
		}
		if warn != nil {
			warnings = append(warnings, sqlWarning{File: path, Line: warn.Line, Col: warn.Col})
		}
	}
	return objects, warnings, nil
}

type statement struct {
	text string
	line int
	col  int
}

// splitStatements splits a SQL file into statements, honoring quoted strings,
// comments and DELIMITER directives.
func splitStatements(contents string) []statement {
	var out []statement
	var sb strings.Builder
	var quote byte
	var inLineComment bool
	var inBlockComment bool
	line := 1
	stmtLine := 0
	stmtCol := 0
	col := 0
	delimiter := ";"
	delimLen := 1
	flush := func() {
		text := strings.TrimRight(sb.String(), "\r\n \t")
		if strings.TrimSpace(text) != "" {
			out = append(out, statement{text: text, line: stmtLine, col: stmtCol})
		}
		sb.Reset()
		stmtLine = 0
		stmtCol = 0
	}
	for i := 0; i < len(contents); i++ {
		c := contents[i]
		if c == '\n' {
			line++
			col = 0
		} else {
			col++
		}
		if inLineComment {
			if c == '\n' {
				inLineComment = false
				if sb.Len() > 0 || stmtLine != 0 {
					sb.WriteByte(c)
				}
			}
			continue
		}
		if inBlockComment {
			if c == '*' && i+1 < len(contents) && contents[i+1] == '/' {
				inBlockComment = false
				i++
				if sb.Len() > 0 || stmtLine != 0 {
					sb.WriteString("*/")
				}
			}
			continue
		}
		if stmtLine == 0 && (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
			continue
		}
		if stmtLine == 0 {
			stmtLine = line
			stmtCol = col
		}
		if quote == 0 {
			// comments
			if c == '-' && i+1 < len(contents) && contents[i+1] == '-' {
				inLineComment = true
				continue
			}
			if c == '#' {
				inLineComment = true
				continue
			}
			if c == '/' && i+1 < len(contents) && contents[i+1] == '*' {
				inBlockComment = true
				i++
				if sb.Len() > 0 {
					sb.WriteString("/*")
				}
				continue
			}
			if c == '\'' || c == '"' || c == '`' {
				quote = c
				sb.WriteByte(c)
				continue
			}
			// delimiter
			if len(contents)-i >= delimLen && contents[i:i+delimLen] == delimiter {
				flush()
				continue
			}
			// DELIMITER directive
			if len(contents)-i >= 9 && strings.EqualFold(contents[i:i+9], "delimiter") {
				// find end of line
				j := i
				for j < len(contents) && contents[j] != '\n' {
					j++
				}
				rest := strings.TrimSpace(contents[i+9 : j])
				if rest != "" {
					delimiter = rest
					delimLen = len(delimiter)
				}
				i = j - 1
				continue
			}
			sb.WriteByte(c)
			continue
		}
		sb.WriteByte(c)
		if c == quote {
			if i+1 < len(contents) && contents[i+1] == quote {
				sb.WriteByte(contents[i+1])
				i++
				continue
			}
			quote = 0
		}
	}
	flush()
	return out
}

// sqlTokens splits a statement into word/symbol tokens, dropping comments.
func sqlTokens(stmt string) []string {
	var tokens []string
	var sb strings.Builder
	var quote byte
	flush := func() {
		if sb.Len() > 0 {
			tokens = append(tokens, sb.String())
			sb.Reset()
		}
	}
	for i := 0; i < len(stmt); i++ {
		c := stmt[i]
		if quote != 0 {
			sb.WriteByte(c)
			if c == quote {
				if i+1 < len(stmt) && stmt[i+1] == quote {
					sb.WriteByte(stmt[i+1])
					i++
					continue
				}
				quote = 0
			}
			continue
		}
		switch {
		case c == '\'' || c == '"' || c == '`':
			flush()
			quote = c
			sb.WriteByte(c)
		case c == ' ' || c == '\t' || c == '\r' || c == '\n':
			flush()
		case c == '(' || c == ')' || c == ',' || c == '=' || c == ';':
			flush()
			tokens = append(tokens, string(c))
		case c == '-' && i+1 < len(stmt) && stmt[i+1] == '-':
			flush()
			return tokens
		case c == '#':
			flush()
			return tokens
		case c == '/' && i+1 < len(stmt) && stmt[i+1] == '*':
			flush()
			// skip block comment
			j := strings.Index(stmt[i:], "*/")
			if j < 0 {
				return tokens
			}
			i += j + 1
		default:
			sb.WriteByte(c)
		}
	}
	flush()
	return tokens
}

// classifyStatement determines whether a statement is a supported CREATE
// statement. Returns an object when it is, nil when it is ignorable, and a
// warning when it is unsupported/unparseable.
func classifyStatement(stmt string, line, col int) (*sqlObject, *sqlWarning) {
