			// skip block comment
			j := strings.Index(stmt[i:], "*/")
			if j < 0 {
				return tokens
			}
			i += j + 1
		default:
			sb.WriteByte(c)
		}
	}
	flush()
	return tokens
}

// classifyStatement determines whether a statement is a supported CREATE
// statement. Returns an object when it is, nil when it is ignorable, and a
// warning when it is unsupported/unparseable.
func classifyStatement(stmt string, line, col int) (*sqlObject, *sqlWarning) {
	tokens := sqlTokens(stmt)
	if len(tokens) == 0 {
		return nil, nil
	}
	lower := strings.ToLower(tokens[0])
	if lower == "use" {
		return nil, nil
	}
	if lower != "create" {
		return nil, &sqlWarning{Line: line, Col: col}
	}
	i := 1
	if i < len(tokens) && strings.EqualFold(tokens[i], "or") {
		if i+1 < len(tokens) && strings.EqualFold(tokens[i+1], "replace") {
			i += 2
		}
	}
	if i < len(tokens) && strings.EqualFold(tokens[i], "definer") {
		i++
		if i < len(tokens) && tokens[i] == "=" {
			i++
		}
		if i < len(tokens) {
			i++
		}
	}
	if i >= len(tokens) {
		return nil, &sqlWarning{Line: line, Col: col}
	}
	objType := strings.ToLower(tokens[i])
	switch objType {
	case "table":
	case "procedure", "function":
	default:
		return nil, &sqlWarning{Line: line, Col: col}
	}
	i++
	if objType == "table" {
		if i < len(tokens) && strings.EqualFold(tokens[i], "temporary") {
			return nil, &sqlWarning{Line: line, Col: col}
		}
	}
	for i < len(tokens) {
		w := strings.ToLower(tokens[i])
		if w == "if" || w == "not" || w == "exists" {
			i++
			continue
		}
		break
	}
	if i >= len(tokens) {
		return nil, &sqlWarning{Line: line, Col: col}
	}
	name := objectNameFromToken(tokens[i])
	if name == "" {
		return nil, &sqlWarning{Line: line, Col: col}
	}
	// For tables, a trailing SELECT clause is not supported.
	if objType == "table" {
		rest := strings.ToLower(strings.Join(tokens[i+1:], " "))
		if strings.Contains(rest, "select") {
			return nil, &sqlWarning{Line: line, Col: col}
		}
	}
	return &sqlObject{Type: objType, Name: name, Line: line, Col: col, Stmt: stmt}, nil
}

// objectNameFromToken extracts the unquoted object name from a token, dropping
// any schema qualifier.
func objectNameFromToken(tok string) string {
	tok = strings.TrimSpace(tok)
	if tok == "" {
		return ""
	}
	if tok[0] == '`' {
		end := strings.Index(tok[1:], "`")
		if end < 0 {
			return tok[1:]
		}
		inner := tok[1 : 1+end]
		inner = strings.Replace(inner, "``", "`", -1)
		return inner
	}
	if idx := strings.LastIndex(tok, "."); idx >= 0 {
		return tok[idx+1:]
	}
	return tok
}

func parseDirObjects(d *dir) ([]sqlObject, []sqlWarning, error) {
	var objects []sqlObject
	var warnings []sqlWarning
	for _, path := range d.SQLFiles {
		contents, err := os.ReadFile(path)
		if err != nil {
			return nil, nil, err
		}
		objs, warns, err := parseSQLFile(path, string(contents))
		if err != nil {
			return nil, nil, err
		}
		objects = append(objects, objs...)
		warnings = append(warnings, warns...)
	}
	return objects, warnings, nil
}
