package main

import "fmt"

// checkDuplicateTables reports an error when the same table name appears more
// than once in a directory's *.sql files.
func checkDuplicateTables(d *dir, objects []sqlObject) error {
	seen := map[string]sqlObject{}
	for _, obj := range objects {
		if obj.Type != "table" {
			continue
		}
		if prev, ok := seen[obj.Name]; ok {
			return fmt.Errorf("table `%s` defined multiple times in same directory: %s line %d and %s line %d", obj.Name, prevLocation(d, prev), prev.Line, locationOf(d, obj), obj.Line)
		}
		seen[obj.Name] = obj
	}
	return nil
}
