import "regexp"

// filterIgnored drops objects whose names match the ignore-table/proc/func
// options.
func filterIgnored(d *dir, env string, objects []sqlObject) []sqlObject {
	values, _ := d.effectiveConfig(env)
	var tableRe, procRe, funcRe *regexp.Regexp
	var err error
	tableRe, err = compileIgnore(values["ignore-table"])
	if err != nil {
		return objects
	}
	procRe, err = compileIgnore(values["ignore-proc"])
	if err != nil {
		return objects
	}
	funcRe, err = compileIgnore(values["ignore-func"])
	if err != nil {
		return objects
	}
	var out []sqlObject
	for _, obj := range objects {
		switch obj.Type {
		case "table":
			if tableRe != nil && tableRe.MatchString(obj.Name) {
				continue
			}
		case "procedure":
			if procRe != nil && procRe.MatchString(obj.Name) {
				continue
			}
		case "function":
			if funcRe != nil && funcRe.MatchString(obj.Name) {
				continue
			}
		}
		out = append(out, obj)
	}
	return out
}

func compileIgnore(pattern string) (*regexp.Regexp, error) {
	if pattern == "" {
		return nil, nil
	}
	return regexp.Compile(pattern)
}
