// resplitStatement splits a statement at its internal terminators (used when a
// compound statement failed to parse).
func resplitStatement(st statement) []statement {
	var out []statement
	var sb strings.Builder
	var quote byte
	line := st.line
	segLine := st.line
	col := st.col
	segCol := st.col
	started := false
	for i := 0; i < len(st.text); i++ {
		c := st.text[i]
		if c == '\\n' {
			line++
			col = 0
		} else {
			col++
		}
		if !started && (c == ' ' || c == '\\t' || c == '\\r' || c == '\\n') {
			continue
		}
		if !started {
			started = true
			segLine = line
			segCol = col
		}
		if quote != 0 {
			sb.WriteByte(c)
			if c == quote {
				if i+1 < len(st.text) && st.text[i+1] == quote {
					sb.WriteByte(st.text[i+1])
					i++
					continue
				}
				quote = 0
			}
			continue
		}
		if c == '\\'' || c == '"' || c == '`' {
			quote = c
			sb.WriteByte(c)
			continue
		}
		if c == ';' {
			text := strings.TrimSpace(sb.String())
			if text != "" {
				out = append(out, statement{text: text, line: segLine, col: segCol})
			}
			sb.Reset()
			started = false
			continue
		}
		sb.WriteByte(c)
	}
	text := strings.TrimSpace(sb.String())
	if text != "" {
		out = append(out, statement{text: text, line: segLine, col: segCol})
	}
	return out
}
