end=s.index('// sqlTokens splits a statement into word/symbol tokens')
new='''// splitStatements splits a SQL file into statements, honoring quoted strings,
// comments and DELIMITER directives.
func splitStatements(contents string) []statement {
	var out []statement
	var sb strings.Builder
	var quote byte
	var inLineComment bool
	var inBlockComment bool
	line := 1
	blockDepth := 0
	stmtLine := 0
	stmtCol := 0
	col := 0
	hasContent := false
	delimiter := ";"
	delimLen := 1
	flush := func() {
		if hasContent {
			text := strings.TrimRight(sb.String(), "\\r\\n \\t")
			if strings.TrimSpace(text) != "" {
				out = append(out, statement{text: text, line: stmtLine, col: stmtCol})
			}
		}
		sb.Reset()
		stmtLine = 0
		stmtCol = 0
		hasContent = false
	}
	for i := 0; i < len(contents); i++ {
		c := contents[i]
		if c == '\\n' {
			line++
			col = 0
		} else {
			col++
		}
		if inLineComment {
			if c == '\\n' {
				inLineComment = false
				if hasContent {
					sb.WriteByte(c)
				}
			}
			continue
		}
		if inBlockComment {
			if c == '*' && i+1 < len(contents) && contents[i+1] == '/' {
				inBlockComment = false
				i++
				if hasContent {
					sb.WriteString("*/")
				}
			}
			continue
		}
		if quote == 0 {
			// comments
			if c == '-' && i+1 < len(contents) && contents[i+1] == '-' {
				inLineComment = true
				continue
			}
			if c == '#' {
				inLineComment = true
				continue
			}
			if c == '/' && i+1 < len(contents) && contents[i+1] == '*' {
				inBlockComment = true
				i++
				if hasContent {
					sb.WriteString("/*")
				}
				continue
			}
			// DELIMITER directive
			if !hasContent && len(contents)-i >= 9 && strings.EqualFold(contents[i:i+9], "delimiter") &&
				(i+9 >= len(contents) || contents[i+9] == ' ' || contents[i+9] == '\\t') {
				j := i
				for j < len(contents) && contents[j] != '\\n' {
					j++
				}
				rest := strings.TrimSpace(contents[i+9 : j])
				if rest != "" {
					delimiter = rest
					delimLen = len(delimiter)
				}
				i = j - 1
				continue
			}
			if c == '\\'' || c == '"' || c == '`' {
				if !hasContent {
					stmtLine = line
					stmtCol = col
					hasContent = true
				}
				quote = c
				sb.WriteByte(c)
				continue
			}
			if len(contents)-i >= delimLen && contents[i:i+delimLen] == delimiter {
				flush()
				continue
			}
			if isWordStart(contents, i) {
				w := wordAt(contents, i)
				lw := strings.ToLower(w)
				switch lw {
				case "begin", "case", "loop", "repeat", "while", "if":
					blockDepth++
				case "end":
					if blockDepth > 0 {
						blockDepth--
					}
					j := i + len(w)
					for j < len(contents) && (contents[j] == ' ' || contents[j] == '\\t' || contents[j] == '\\n' || contents[j] == '\\r') {
						j++
					}
					if j < len(contents) && isWordStart(contents, j) {
						w2 := wordAt(contents, j)
						l2 := strings.ToLower(w2)
						if l2 == "if" || l2 == "case" || l2 == "loop" || l2 == "repeat" || l2 == "while" {
							if !hasContent {
								stmtLine = line
								stmtCol = col
								hasContent = true
							}
							sb.WriteString(w)
							sb.WriteString(contents[i+len(w) : j+len(w2)])
							i = j + len(w2) - 1
							continue
						}
					}
				}
				if !hasContent {
					stmtLine = line
					stmtCol = col
					hasContent = true
				}
				sb.WriteString(w)
				i += len(w) - 1
				continue
			}
			if c == ' ' || c == '\\t' || c == '\\r' || c == '\\n' {
				if hasContent {
					sb.WriteByte(c)
				}
				continue
			}
			if !hasContent {
				stmtLine = line
				stmtCol = col
				hasContent = true
			}
			sb.WriteByte(c)
			continue
		}
		sb.WriteByte(c)
		if c == quote {
			if i+1 < len(contents) && contents[i+1] == quote {
				sb.WriteByte(contents[i+1])
				i++
				continue
			}
			quote = 0
		}
	}
	flush()
	return out
}

'''
