s=open('sqlparse.go').read()
s=s.replace('''// sqlTokens splits a statement into word/symbol tokens, dropping comments.''','''// isWordStart reports whether position i begins an identifier.
func isWordStart(s string, i int) bool {
	c := s[i]
	if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c == '_' {
		if i > 0 {
			p := s[i-1]
			if p >= 'a' && p <= 'z' || p >= 'A' && p <= 'Z' || p >= '0' && p <= '9' || p == '_' || p == '$' {
				return false
			}
		}
		return true
	}
	return false
}

// wordAt returns the identifier starting at position i.
func wordAt(s string, i int) string {
	j := i
	for j < len(s) {
		c := s[j]
		if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '$' {
			j++
			continue
		}
		break
	}
