new = '''// splitStatements splits a SQL file into statements, honoring quoted strings,
// comments and DELIMITER directives. An error is returned for unterminated
// comments or strings.
func splitStatements(contents string) ([]statement, error) {
	var out []statement
	var sb strings.Builder
	var quote byte
	var inLineComment bool
	var inBlockComment bool
	var blockCommentLine int
	var quoteLine int
	var quoteCol int
	line := 1
	blockDepth := 0
	stmtLine := 0
	stmtCol := 0
	col := 0
	hasContent := false
	stmtInternal := false
	delimiter := ";"
	delimLen := 1
	flush := func() {
		if hasContent {
			text := strings.TrimRight(sb.String(), "\\r\\n \\t")
			if strings.TrimSpace(text) != "" {
				out = append(out, statement{text: text, line: stmtLine, col: stmtCol, internal: stmtInternal})
			}
		}
		sb.Reset()
		stmtLine = 0
		stmtCol = 0
		hasContent = false
		stmtInternal = false
	}
	for i := 0; i < len(contents); i++ {
		c := contents[i]
		if c == '\\n' {
			line++
			col = 0
		} else {
			col++
		}
		if inLineComment {
			if c == '\\n' {
				inLineComment = false
				if hasContent {
					sb.WriteByte(c)
				}
			}
			continue
		}
		if inBlockComment {
			if c == '*' && i+1 < len(contents) && contents[i+1] == '/' {
				inBlockComment = false
				i++
				col++
				if hasContent {
					sb.WriteString("*/")
				}
			}
			continue
		}
		if quote == 0 {
			// comments
			if c == '-' && i+1 < len(contents) && contents[i+1] == '-' {
				inLineComment = true
				continue
			}
			if c == '#' {
				inLineComment = true
				continue
			}
			if c == '/' && i+1 < len(contents) && contents[i+1] == '*' {
				inBlockComment = true
				blockCommentLine = line
				i++
				col++
				if hasContent {
					sb.WriteString("/*")
				}
				continue
			}
			// DELIMITER directive
			if !hasContent && len(contents)-i >= 9 && strings.EqualFold(contents[i:i+9], "delimiter") &&
				(i+9 >= len(contents) || !isWordChar(contents[i+9])) {
				j := i
				for j < len(contents) && contents[j] != '\\n' {
					j++
				}
				rest := strings.TrimSpace(contents[i+9 : j])
				if rest != "" {
					delimiter = rest
					delimLen = len(delimiter)
				}
				i = j - 1
				continue
			}
			if c == '\\'' || c == '"' || c == '`' {
				if !hasContent {
					stmtLine = line
					stmtCol = col
					hasContent = true
				}
				quote = c
				quoteLine = line
				quoteCol = col
				if c != '`' {
					// track for unterminated detection
