function.arguments:
{"command": "cd /workspace && cat > flavor.go <<'GOEOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// flavor describes a database server vendor/version, as configured with the
// flavor option for workspace=docker.
type flavor struct {
	vendor  string
	version float64
	known   bool
}

var knownFlavorVendors = map[string]string{
	"mysql":   "MySQL",
	"mariadb": "MariaDB",
	"percona": "MySQL",
	"aurora":  "MySQL",
}

// parseFlavor parses a flavor option value.
func parseFlavor(s string) (flavor, error) {
	f := flavor{}
	idx := strings.Index(s, ":")
	if idx < 0 {
		f.vendor = strings.ToLower(s)
		f.version = 0
	} else {
		f.vendor = strings.ToLower(s[:idx])
		v, err := strconv.ParseFloat(strings.TrimSpace(s[idx+1:]), 64)
		if err != nil || v < 0 {
			f.version = 0
		} else {
			f.version = v
		}
	}
	display, ok := knownFlavorVendors[f.vendor]
	f.known = ok
	if !ok {
		if f.version == 0 {
			return f, fmt.Errorf("no flavor supplied")
		}
		return f, flavorWarnError{fmt.Sprintf("Flavor unknown:%s is not recognized, and may not work properly with workspace=docker", trimVersion(f.version))}
	}
	_ = display
	switch f.vendor {
	case "aurora":
		return f, flavorFatalError{fmt.Sprintf("MySQL %s is not supported by Skeema.", trimVersion(f.version))}
	case "mariadb":
		if f.version < 10.1 {
			return f, flavorFatalError{fmt.Sprintf("MariaDB %s is not supported by Skeema.", trimVersion(f.version))}
		}
		if f.version == 10.1 {
			return f, flavorWarnError{"workspace=docker: MariaDB 10.1 is deprecated in this release of Skeema. The next major version of Skeema will likely drop support for this database server."}
		}
		if f.version > 12.99 {
			return f, flavorWarnError{fmt.Sprintf("workspace=docker: MariaDB %s is newer than this release of Skeema. To ensure correct behavior, upgrade to a more recent release of Skeema.", trimVersion(f.version))}
		}
	default:
		if f.version < 5.6 {
			return f, flavorFatalError{fmt.Sprintf("MySQL %s is not supported by Skeema.", trimVersion(f.version))}
		}
		if f.version == 5.5 {
			return f, flavorWarnError{"workspace=docker: MySQL 5.5 is deprecated in this release of Skeema. The next major version of Skeema will likely drop support for this database server."}
		}
		if f.version > 9.99 {
			return f, flavorWarnError{fmt.Sprintf("workspace=docker: MySQL %s is newer than this release of Skeema. To ensure correct behavior, upgrade to a more recent release of Skeema.", trimVersion(f.version))}
		}
	}
	return f, nil
}

// trimVersion renders a version with one decimal place (matching the original's
// formatting for integer-ish versions).
func trimVersion(v float64) string {
	s := strconv.FormatFloat(v, 'f', -1, 64)
	if !strings.Contains(s, ".") {
		s += ".0"
	}
	return s
}

// flavorWarnError is a non-fatal flavor problem.
type flavorWarnError struct{ msg string }

func (e flavorWarnError) Error() string { return e.msg }

// flavorFatalError is a fatal flavor problem.
type flavorFatalError struct{ msg string }

func (e flavorFatalError) Error() string { return e.msg }
GOEOF
