{"command": "cd /workspace && cat > flavor.go <<'GOEOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// version is a database server version, compared as major.minor.
type version struct {
	major int
	minor int
	set   bool
}

func (v version) less(o version) bool {
	if v.major != o.major {
		return v.major < o.major
	}
	return v.minor < o.minor
}

func (v version) equal(o version) bool { return v.major == o.major && v.minor == o.minor }

func (v version) greater(o version) bool {
	if v.major != o.major {
		return v.major > o.major
	}
	return v.minor > o.minor
}

func (v version) String() string {
	return fmt.Sprintf("%d.%d", v.major, v.minor)
}

// parseVersion extracts a major.minor version from the leading numeric part of
// a flavor version string.
func parseVersion(s string) version {
	i := 0
	for i < len(s) && (s[i] >= '0' && s[i] <= '9' || s[i] == '.') {
		i++
	}
	s = s[:i]
	parts := strings.SplitN(s, ".", 3)
	v := version{}
	if len(parts) == 0 || parts[0] == "" {
		return v
	}
	major, err := strconv.Atoi(parts[0])
	if err != nil {
		return version{}
	}
	v.major = major
	if len(parts) > 1 {
		minor, _ := strconv.Atoi(parts[1])
		v.minor = minor
	}
	v.set = true
	return v
}

var knownFlavorVendors = map[string]string{
	"mysql":   "MySQL",
	"mariadb": "MariaDB",
	"percona": "MySQL",
	"aurora":  "MySQL",
}

// parseFlavor validates a flavor option value, returning a non-nil error for
// problems (warnings for unrecognized vendors/versions, fatal errors for
// unsupported ones).
func parseFlavor(s string) error {
	idx := strings.Index(s, ":")
	var vendor string
	ver := version{}
	if idx < 0 {
		vendor = s
	} else {
		vendor = s[:idx]
		ver = parseVersion(s[idx+1:])
	}
	if _, ok := knownFlavorVendors[vendor]; !ok {
		if !ver.set {
			return flavorFatalError{"no flavor supplied"}
		}
		return flavorWarnError{fmt.Sprintf("Flavor unknown:%s is not recognized, and may not work properly with workspace=docker", ver.String())}
	}
	if !ver.set {
		return flavorWarnError{fmt.Sprintf("Flavor %s:%s is not recognized, and may not work properly with workspace=docker", vendor, ver.String())}
	}
	switch vendor {
	case "aurora":
		return flavorFatalError{fmt.Sprintf("MySQL %s is not supported by Skeema.", ver.String())}
	case "mariadb":
		if ver.equal(version{10, 1, true}) {
			return flavorWarnError{"workspace=docker: MariaDB 10.1 is deprecated in this release of Skeema. The next major version of Skeema will likely drop support for this database server."}
		}
		if ver.less(version{10, 1, true}) {
			return flavorFatalError{fmt.Sprintf("MariaDB %s is not supported by Skeema.", ver.String())}
		}
		if ver.greater(version{12, 99, true}) {
			return flavorWarnError{fmt.Sprintf("workspace=docker: MariaDB %s is newer than this release of Skeema. To ensure correct behavior, upgrade to a more recent release of Skeema.", ver.String())}
		}
	default:
		if ver.equal(version{5, 5, true}) {
			return flavorWarnError{"workspace=docker: MySQL 5.5 is deprecated in this release of Skeema. The next major version of Skeema will likely drop support for this database server."}
		}
		if ver.less(version{5, 6, true}) {
			return flavorFatalError{fmt.Sprintf("MySQL %s is not supported by Skeema.", ver.String())}
		}
		if ver.greater(version{9, 99, true}) {
			return flavorWarnError{fmt.Sprintf("workspace=docker: MySQL %s is newer than this release of Skeema. To ensure correct behavior, upgrade to a more recent release of Skeema.", ver.String())}
		}
	}
	return nil
}

// flavorWarnError is a non-fatal flavor problem.
type flavorWarnError struct{ msg string }

func (e flavorWarnError) Error() string { return e.msg }

// flavorFatalError is a fatal flavor problem.
type flavorFatalError struct{ msg string }

func (e flavorFatalError) Error() string { return e.msg }
GOEOF
