func processSchemaDir(d *dir, env string, firstOnly bool) bool {
	values, order := d.effectiveConfig(env)
	if values["host"] == "" {
		logWarnf("Skipping %s: no host defined for environment %q", d.Path, env)
		logWarnf("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", env)
		return false
	}''','''// processDirParse parses a dir's *.sql files, reporting fatal parse problems.
// Returns true when the dir is OK. When the dir has no objects and only
// unparseable statements, nothing is reported for diff/push.
func processDirParse(d *dir, env string, warnUnparseable bool) bool {
	objects, _, perr := parseDirObjects(d)
	if perr != nil {
		logErrorf("Skipping %s: %v", d.Path, perr)
		return false
	}
	objects = filterIgnored(d, env, objects)
	if dupErr := checkDuplicateTables(d, objects); dupErr != nil {
		logErrorf("Skipping %s: %v", d.Path, dupErr)
		return false
	}
	_ = objects
	return true
}

// processSchemaDir handles one schema dir for diff/push. Returns true when the
// dir had to be skipped.
func processSchemaDir(d *dir, env string, firstOnly bool) bool {
	values, order := d.effectiveConfig(env)
	if values["host"] == "" {
		logWarnf("Skipping %s: no host defined for environment %q", d.Path, env)
		if values["host-wrapper"] != "" {
			logWarnf("The host-wrapper option controls which hosts this directory maps to, but the executed script returned no hostnames.")
		} else {
			logWarnf("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", env)
		}
		return false
	}''')
