package main

import (
	"fmt"
	"strings"
)

// parseConnectOptions parses a comma-separated list of key=value session
// options, mimicking the original binary's validation.
func parseConnectOptions(s string) (map[string]string, error) {
	opts := map[string]string{}
	if s == "" {
		return opts, nil
	}
	parts := strings.Split(s, ",")
	offset := 0
	for _, part := range parts {
		if part == "" {
			return nil, connectOptsError{fmt.Sprintf("Invalid comma placement in option value at byte offset %d in connect-options %q", offset, s)}
		}
		idx := strings.Index(part, "=")
		if idx < 0 {
			return nil, connectOptsError{fmt.Sprintf("Option %s is missing a value at byte offset %d in connect-options %q", part, offset+len(part), s)}
		}
		key := part[:idx]
		val := part[idx+1:]
		if key == "" {
			if strings.Contains(val, "=") {
				return nil, connectOptsError{fmt.Sprintf("Invalid comma placement in option value at byte offset %d in connect-options %q", offset+len(part), s)}
			}
			return nil, connectOptsError{fmt.Sprintf("Option %s is missing a value at byte offset %d in connect-options %q", val, offset+len(part), s)}
		}
		if eqIdx := strings.Index(val, "="); eqIdx >= 0 {
			return nil, connectOptsError{fmt.Sprintf("Invalid equals-sign character in option value at byte offset %d in connect-options %q", offset+idx+1+eqIdx, s)}
		}
		if val == "" {
			return nil, connectOptsError{fmt.Sprintf("Invalid comma placement in option value at byte offset %d in connect-options %q", offset+idx+1, s)}
		}
		opts[key] = val
		offset += len(part) + 1
	}
	return opts, nil
}

// connectOptsError is an invalid connect-options value.
type connectOptsError struct{ msg string }

func (e connectOptsError) Error() string { return e.msg }
GOEOF
