import socket, sys, threading, time
mode = sys.argv[1]
port = int(sys.argv[2])
s = socket.socket()
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
s.bind(('127.0.0.1', port)); s.listen(5)
def handle(c):
    try:
        if mode == 'close':
            c.close(); return
        if mode == 'garbage':
            c.sendall(b'garbage\n'); time.sleep(0.2); c.close(); return
        if mode == 'hang':
            time.sleep(3); c.close(); return
        if mode == 'err':
            # MySQL error packet: header(4) + 0xff + errno(2) + sqlstate + msg
            payload = b'\xff' + (1045).to_bytes(2,'little') + b'#28000' + b"Access denied for user 'root'@'localhost' (using password: NO)"
            c.sendall(len(payload).to_bytes(3,'little') + b'\x00' + payload)
            time.sleep(0.5); c.close(); return
    except Exception: pass
while True:
    c, _ = s.accept()
    threading.Thread(target=handle, args=(c,), daemon=True).start()
